insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (139,'مذكرات الرئيس','مذكرة رقم 2/ه.ش.ع./٢٠٢٦ - موجَّهة إلى كافَّة الجهات الخاضعة لأحكام قانون الشراء العام حول آليَّة تطبيق الفقرة الرابعة من المادَّة ٤٦ من قانون الشراء العام (شروط الاتفاق الرضائي للوازم والأشغال والخدمات ذات الطابع السري)','2026-01-21','https://www.ppa.gov.lb/ar/pages/details/139','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Akcdtge7aAbmXzIqGWef3AAX6jfWh7iEsLHm-1770102426.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Akcdtge7aAbmXzIqGWef3AAX6jfWh7iEsLHm-1770102426.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=139),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "1“ الجمهوريّة اللبنانيتة\n0 سيئة الشراء العام\nمذكرة رقم '/هرش.ع./5 ٠١7\nموجَّهة إلى كافّة الجهات الخاضعة لأحكام قانون الشراء العام\nحول آلبّة تطبيق الفقرة الرابعة من المادّة 45 من قانون الشراء العام\n(شروط الاتفاق الرضائي للوازم والأشغال والخدمات ذات الطابع السري)\nبناءٌ على قانون الشراء العام رقم ؛ 4 ؟ تاريخ ٠١ 7١/7/١4 المعدل بالقانون رقم \"٠١5 تاريخ 27١1/4/١5\nلاسيّما المواد 45)» \"/ و88 منه,\nوبما أنَّ المادّة 7 من قانون الشراء العام تنصصٌ في الفقرة رقم 8 منها على أنّهُ من مهام هيئة الشراء العام \"\nإصدار إرشادات وتوضيحات حول النصوص القانونيّة النافذة المتعلّقة بالشراء العام؛ بما في ذلك إصدار الأدلّة\nوالقواعد الإرشاديّة \"\nوبما أنَّ المادّة 75 من قانون الشراء العام تنص في الفقرة رقم 1 منها على أنَّهُ من مهام هيئة الشراء العام\n'امراقبة وتقييم النصوص القانونيّة التي ترعى الشراء العامء ويحق لها في هذا الإطار الاطلاع على سجل\nالشراء لدى الجهة الشاريّة: مع مراعاة سريّة البيانات بحسب أحكام المادّة 7 من هذا القانون. تُنظّم الهينة\nتقارير دوريّة تتناول مكامن الخلل و/أو مخالفة القوانين في كل الجهات الشاريةء وترفعها إلى رئاسة\nالجمهوريّة ومجلس النوّاب ومجلس الوزراء وديوان المحاسبة والتفتيش المركزي وتنشرها وفق الأصول \".\nوبما أنَّ المادّة 77 من قانون الشراء العام تنصصُ في الققرة رقم ١5 منها على أنّهُ من مهام هيئة الشراء العام أيضاً\n'امعالجة وتحليل المعلومات الخاصّة بعمليّات الشراء العامء ووضع واصدار معايير الأداء وتحرير تقارير\nتحليليّة وإحصايّة ونشرها \".\nوبما أنَّ المادّة 7 من قانون الشراء العام تنص في الفقرة رقم ١5 منها على أنَّهُ من مهام هيئة الشراء العام أيضاً\n\"إصدار مستندات ونماذج معياريّة لإجراءات الشراء العام بما فيها دفاتر الشروط النموذجيّة وملفات التأهيل"}, {"o": 1, "l": null, "b": "النموذجيّةء وتوفيرها للجهات الشارية لاعتمادها الزاميًاً \".\nوبما أنّ المادّة 5 من قانون الشراء العام تنصصُ في الفقرة رقم 49 منها على أنَّهُ من مهام هيئة الشراء العام\n\"وضع الإرشادات والكتيّبات والتوضيحات في ما يتعلق بقواعد وإجراءات الشراء العام وتقديم النصح\nوالمساعدة والخبرات للجهات الشارية والعارضين المحتملينء وتوفير المعكلومات عبر المنصّة الإلكترونيّة\nالموكّدة المعتمدة \".\nوبما أن المادة 45 فقرة ؛ من قانون الشراء العام تجيز استثنائيًا التعاقد بالتراضي: \"عند شراء لواز مأو خدمات\nأو عند تنفيذ أشغال تستوجب المحافظة على طابعها السري من أجل مقتضيات الأمن أو الدفاع الوطنيء وذلك\nوفقاً لقرار يُتَحَذْ في مجلس الوزراء بناءً على اقتراح الوزير المختص الذي يُحدّد الصفة السرية للشراء\nوأسباب التعاقد الرضائي؛\" 2\nونا ”7 0\nمن\nع 2 1\nايده . منعيحه :' ١ فحة 2/1\n7\nك0 الجمهوريّة اللبنانيتة\n222 مهيئةالشراء العام\nوبما أن نص الفقرة 5 من المادّة 5 ؟ من قانون الشراء العام واضح لجهة وجوب تحديد \"أسباب التعاقد الرضائي\nللوازم والأشغال والخدمات ذات الطابع السري\" الذي يختلف من عقد لآخرء وبالتالي يجب على الجهة الشارية\nفي كل مرّة أرادت التعاقد بالتراضي لمقتضيات السريّة الاستحصال على قرار من مجلس الوزراء يتيح لها هذا\nالتعاقد مع تبيان أسبابه»\nوبما أن أي إساءة في استخدام الفقرة ؛ من المادة 45 من قانون الشراء العام» بالاستناد إلى موافقات سابقة\nصادرة عن مجلس الوزراء في مواضيع مشابهة أو ذات صلة أو حتى أحيانًا متباعدة لتمرير عمليات شراء\nلوازم أو أشغال أو خدمات قد لا تكون ذات طابع سريء تؤدي في حال حصولها إلى إخراج هذه الاتفاقيات\nالرضائية من دائرة رقابة مجلس الوزراءء كما أن الهيئات الرقابية المختصة قد لا تعلم حتى باجراء هذه الاتفاقيات\nفتزداد احتمالات التلاعب وتضارب المصالح وصرف النفوذ»\nلذلك."}, {"o": 2, "l": null, "b": "تطلب هيئة الشراء العام من الجهات الخاضعة لأحكام قانون الشراء العام:\n-١ اعتبار أي قرار صادر بالاستناد إلى الفقرة (4) من المادّة 45 من قانون الشراء العام منقضي المفعول\nبعد اجراء الاتفاق الرضائي للوازم والأشغال والخدمات ذات الطابع السري المسند إليه.\n\"- وجوب تقديم طلب منفصل لمجلس الوزراء عبر الوزير المختص في كل مرّة أرادت الجهة الشارية\nإجراء عقد اتفاق رضائي سندًا للمادة 57 فقرة (4) من قانون الشراء العام تبيّن فيه:\nأ. كيفيّة انطباق توصيف \"الأمن\" أو \"الدفاع الوطني\" على موضوع الاتفاق الرضائي المطلوب.\nب. الأسباب الموجبة لاعطاء اللوازم والأشغال او الخدمات موضوع التعاقد الطابع السري.\nيُعمل بهذه المذكرة من تاريخ نشرها على المنصة الالكترونية المركزية لدى هيئة الشراء العام الذي يعتبر بمثابة\nتبليغ للجهات الشارية عملا بأحكام الفقرة 5 من المادة (؟) من قانون الشراء العام.\n2 بيروت في ٠١75/01/5١\n6 7 ُ/ رئيس هيئة الشراء العام\n١ 0 0\nا 75 د\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (140,'مذكرات الرئيس','مذكرة رقم 3/ه.ش.ع./٢٠٢٦ موجَّهة إلى كافَّة الجهات الخاضعة لأحكام قانون الشراء العام حول موجب التصريح عن معلومات أصحاب الحقوق الاقتصاديَّة من قبل العارضين','2026-01-21','https://www.ppa.gov.lb/ar/pages/details/140','{"https://admin.ppa.gov.lb/storage/listing-pages/files/7kA9z1xMl1QWeqSFPuEtjcpqaLp3CIyZp4Oh-1770102498.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/7kA9z1xMl1QWeqSFPuEtjcpqaLp3CIyZp4Oh-1770102498.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=140),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "الجمهوريّة اللبنانيتة\nور سيئة الشراء العام\nالهف شفافية ٠ منافسة ٠ه نزاهة\nمذكرة رقم '/هرش.ع./57 ٠١7\nموجَّهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام\nحول موجب التصريح عن معلومات أصحاب الحقوق الاقتصاديّة من قبل العارضين\nبناءً على قانون الشراء العام رقم ؛ 4 ؟ تاريخ ٠١71/17/15 المعدل بالقانون رقم \"٠١5 تاريخ 2”7٠171/4/١5\nلاسيّما المواد لا. 5/ا و88 منه,\nبناء على مذكرة هيئة الشراء العام رقم 5/ه.رش.ع/ 7٠١71 تاريخ ١77/04/07 5؟» التي تلزم العارضين التصريح\nعن معلومات أصحاب الحقوق الاقتصاديّة بموجب النموذج \"م \"١6 الصادر عن وزارة الماليّة» المسندة إلى\nالمادّة /! - معدّلة من قانون الشراء العام التي تنص على أنّ إحدى شروط المشاركة في عمليّات الشراء العام\nهي التصريح من قبل العارضين عن معلومات أصحاب الحقوق الاقتصاديّة لكل عارض:\n٠\" . يجب أن تتوافر في العارضين الشروط التالية» إضافةً إلى أي شروط تراها الجهة الشارية مناسبة وذات\nصلة بموضوع الشراء:\nي. التصريح عن أصحاب الحق الاقتصادي حنّ ىآخر درجة ملكيّة \"\nوبما أن المادّة 75 من قانون الشراء العام تنصصٌ في الفقرة رقم ؟ منها على أنَّهُ من مهام هيئة الشراء العام \"مراقبة\nوتقييم النصوص القانونيّة التي ترعى الشراء العام؛ ويحق لها في هذا الإطار الاطلاع على سجل الشراء لدى\nالجهة الشاريّة» مع مراعاة سريّة البيانات بحسب أحكام المادّة \" من هذا القانون.تُنظّم الهيئة تقارير دوريّة تتناول\nمكامن الخلل و,أو مخالفة القوانين في كل الجهات الشارية» وترفعها الى رئاسة الجمهوريّة ومجلس النوّاب\nومجلس الوزراء وديوان المحاسبة والتفتيش المركزي وتنشرها وفق الأصول \".\nوبما أنَّ المادّة 77 من قانون الشراء العام تنص في الفقرة رقم ١١ منها على أَنَّهُ من مهام هيئة الشراء العام"}, {"o": 1, "l": null, "b": "الجمع البيانات والمستندات الخاصّة بالشراء العامء على كاقّة المستويات» على المنصّة المركزيّة بما في ذلك\nأنواع وطرق التعاقد والقطاعات الاقتصاديّة المشاركة وبيانات تنفيذ المشاريع المموّلة من جهات مانحة وغيرهاء\nوذلك في قاعدة بيانات مركزيّة لديهاء بشكل يتيح سهولة قراءة وتحليل هذه البيانات والمستندات وبحسب المعايير\nالدوليّة المعتمدة في هذا المجال \".\nوبما أنَّ المادّة 5 من قانون الشراء العام تنصصٌُ في الفقرة رقم ١5 منها على أَنّهُ من مهام هيئة الشراء العام أيضاً\n| 'معالجة وتحليل المعلومات الخاصّة بعمليّات الشراء العام ووضع وإصدار معايير الأداء وتحري رتقاري رتحليليّة\n| وإحصائيّة ونش رها\".\nا وبما أنّ المادّة 7 (معدّلة) من قانون الشراء العام توجب استبعاد أي عارض لم يقم بالتصريح عن معلومات\nأصحاب الحقوق الاقتصاديّة الخاصّة به بشكل تلقائي»\nوبما أن عدم استبعاد العارضين الذين لم يصرّحوا بمعلومات أصحاب الحقوق الاقتصاديّة عن عمليات الشراء\nالعام يشكّل مخالفة صريحة لنص القانون» ويجعل أي عمليّة شراء يتم تلزيمها لعارض لم يصرّح بهذه المعلومات\nعُرضة للطعن والإيطال»\nْ\n2 2\nمسار تا\nكه ف صفحة 2/1\nث0 الجمصوريّة اللبنانيتة\n0-2 هسيئة الشراء العام\nوكي يتسنَّى لهيئة الشراء العام ممارسة مهامها المنصوص عنها في المادّة \"7 من قانون الشراء العام والاطلاع\nعلى المعلومات عن أصحاب الحقوق الاقتصاديّة التي يتم التصريح عنها من قبل العارضين كما الاطلاع على\nأسماء العارضين الذين لم يصرّحوا عن هذه المعلومات»\nلذلكء\nتطلب هيئة الشراء العام من كافة الجهات الخاضعة لأحكام قانون الشراء العام:\n-١ استبعاد أي عارض لا يقدم التصريح عن معلومات أصحاب الحقوق الاقتصاديّة الخاصّة به.\n؟- لغايات التدقيق» إفادتنا عما إذا كان قد تمَّ قبول عارضين لم يقدّموا تصريحًا عن معلومات أصحاب الحقوق"}, {"o": 2, "l": null, "b": "الاقتصاديّة الخاصّة بهم» كما وتزويدنا بأسماء هؤلاء العارضين للتدقيق فيها وذلك عن الفترة الممتدة من\n48 حنّى تاريخ صدور هذه المذكرة.\n'- ارسال المعلومات المطلوبة بمقتضى البند (؟) أعلاه إلى هيئة الشراء العام إلكترونيًا على البريد الالكتروني\nلهيئة الشراء العام في مهلة أقصاها شهر من تاريخ نشر هذه المذكرة على المنصة الإلكترونية المركزية\nلدى هيئة الشراء العام.\nيُعمل بهذه المذكرة من تاريخ نشرها على المنصة الالكترونية المركزية لدى هيئة الشراء العام الذي يعتبر بمثابة\nتبليغ للجهات الشارية عملا بأحكام الفقرة ١” من المادة )١( من قانون الشراء العام.\nبيروت في ٠١75/01/5١\n2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (141,'مذكرات الرئيس','مذكرة رقم 4/ه.ش.ع./٢٠٢٦ موجَّهة إلى كافَّة الجهات الخاضعة لأحكام قانون الشراء العام بموضوع العرض المرتفع سعره بشكل غير اعتيادي','2026-01-27','https://www.ppa.gov.lb/ar/pages/details/141','{"https://admin.ppa.gov.lb/storage/listing-pages/files/U4OByi6JoGK4irkHczT8ejbZeoOtKAQgd4Lk-1770102339.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/U4OByi6JoGK4irkHczT8ejbZeoOtKAQgd4Lk-1770102339.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=141),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "5“ الجمهوريّة اللبنانيتة\nفته هيئةالشراء العام\nمذكرة رقم ؛/ه.ش.ع./\" ٠١7\nموجّهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام\nبشأن العرض المرتفع سعره بشكل غير إعتيادي\nبناءً على قانون الشراء العام رقم ؛ ؛ ١ تاريخ 7١7١/17/١5 المعدل بالقانون رقم \"١5 تاريخ 25١7/4/١5\nسيّما المادتين \"/ا و88 منه؛,\nوبما أن المادة 17” من قانون الشراء العام قد نصت على ما يلي:\n-١ يجوز للجهة الشارية أن ترفض أي عرض اذا قررت أن السعرء مقترناً بسائر العناصر المكتونة لذلك\nالعرض المقدم؛ منخفض انخفاضاً غير عادي قياساً الى موضوع الشراء وقيمته التقديريةء وأنه يثير الشك\nلديها بشأن قدرة العارض على تنفيذ العقدء وذلك شر طأن تكون الجهة الشارية قد طلبت من العارض المعني\nخطياً تفاصيل العرض المقدم بشكل يسمح لها بتحليل المعلومات التفصيلية واستنتاج ما اذا كان العارض\nسيكون قادراً على تنفيذ عقد الشراء بالسعر المقدم. من التفاصيل التي يمك ن أن تطلبها الجهة الشاريةء على\nسبيل المثال لا الحصرء\n- معلومات وعبّنات أو ما يشابههاء ثبت جودة موضوع الشراء المقدم في العرض»\nبعد طرق التصنيع ذات الصلةء\nج- الحلول التقنية المختارة و/أ و أي شروط مُؤاتية بشكل استثنائي متاحة لتنفيذ العقد موضوع الشراء.\n-١ يدرج في تقرير التقييم قرار الجهة الشارية برفض عرض ما وفقاً لأحكام هذه المادةء وأسباب ذلك القرار\nوكل الايضاحات التي جرت مع العارضين. يبلغ العارض المعنيء على الفورء بقرار الجهة الشارية\nوأسبابه\" .\nوبما أن المادة 75 فقرة )١( من قانون الشراء العام قد نصت على ما يلي:\n\"إلغاء الشراء و/أ و أي من اجراءاته.\nيمكن للجهة الشارية أن تُلغي الشراء و أو أي من إجراءاته ف يأيٌّ وقت قبل ابلاغ الملتزم المؤقت ايرام العقدء\nفي الحالات التالية:\nأ. عندما تجد الجهة الشارية ضرورة إحداث تغييرات جوهرية غير متوفعة على ملفات التلزيم بعد الإعلان\nعن الشراءء"}, {"o": 1, "l": null, "b": "ب. عندما تط رأ تغييرات غير متوقعة على موازنة الجهة الشارية؛\nج. عندما تنتفي الحاجة لموضوع الشراء نتيجة ظروف غير متوقعة وموضوعية وعندها لا نيعاد التلزيم خلال\nالموازنة أو السنة الماليّة نفسها\".\nوبما أن المادة 75 فقرة )١( من قانون الشراء العام قد نصت على ما يلي:\n\"كما يمكنها إلغاء الشراء و/أ و أي من إجراءاته اذا لم يقد م أي عرض و/أو قدمت عروض غير مقبولة\".\nوبما أن المادة 5ه فقرة (4) من قانون الشراء العام قد نصت على أن ترفض الجهة الشارية العرض اذا كان\nغير مستجيب جوهرياً للمتطلبات المحددة في ملف التلزيم.\nعا ادقع ) ))\n00\nحصا لسوت ١\nا\n- ا صفحة 2/1\nالجمهوريّة اللبنانيتة\nور هسيئة الشراء العام\nوبما أن المادة 57 فقرة (ع) من قانون الشراء العام قد نصت على ما يلي: \" معابير واجراءات تقييم العروض\nبناءً على وصف موضوع الشراء \" »\nوفي فقرتها (ت) قد نصت على ما يلي:. \"أي شروط إضافية تقررها الجهة الشارية بما يتوافق مع هذا القانون\nومراسمه التطبيفيّة\" .\nوبما أن قانون الشراء العام لم يلحظ أحكاماً خاصة بموضوع الحالة التي يكون فيها سعر العرض الفائز مرتفعًا\nارتفاعًا غير اعتيادي عن القيمة التقديرية الموضوعة من قبل الجهة الشارية»\nوبما أن قانون الشراء العام قد ناط بالجهة الشارية تحديد معايير استجابة العروض ورفض أي عرض غير\nمستجيب جوهريًا للمتطلبات المحددة في ملفات التلزيم.\nلذلكء\nتطلب هيئة الشراء العام من كافة الجهات الخاضعة لأحكام قانون الشراء العام إدراج نصّ في دفتر الشروط\nالخاص بالصفقة سنداً لأحكام المادة ؟ © - الفقرتين - (ع) و(ت)» يتعلق بكيفية تقييم العروض المرتفعة بشكل\nغير إعتيادي عن القيمة التقديرية والتقيّد به عند إجراء عمليّة التلزيم.\nبيروت في 7075/01/71\nرئيس هيئة الشراء العام\n0\n3 بور 4 ى\n0 5"}, {"o": 2, "l": null, "b": "ملاحظة: يعمل بهذه المذكرة من تاريخ نشرها على المنصة الالكترونية المركزية لدى هيئة الشراء العام الذي يعتبر بمثابة تبليغ\nللجهات الشارية عملا بأحكام الفقرة 5” من المادة (؟) من قانون الشراء العام.\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (142,'مذكرات الرئيس','مذكرة رقم 5/ه.ش.ع./٢٠٢٦ موجَّهة إلى كافَّة الجهات الخاضعة لأحكام قانون الشراء العام بموضوع سجل الشراء','2026-01-27','https://www.ppa.gov.lb/ar/pages/details/142','{"https://admin.ppa.gov.lb/storage/listing-pages/files/lBAH6FkJ5nuv2wL4MgSKCDQvOgaEnboS7kiY-1769604334.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/lBAH6FkJ5nuv2wL4MgSKCDQvOgaEnboS7kiY-1769604334.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=142),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "الجمهوريّة اللبنائيتة\nور سيئة الشراء العام\nمذكرة رقم هإه.ش.ع./77 ٠١\n5 مه ايع 5\nموجّهة إلى كافه الجهات الخاضعة لأحكام قانون الشراء العام\nبموضوع سجل الشراء\nإنَّ رئيس هيئة الشراء العام»\nبناء على قانون الشراء العام رقم ١44 تاريخ ٠١7١/17/١3 المعدل بالقانون رقم 05\" تاريخ 23075/4/15\nسيّما المواد 5لا و 88 منهء\nويما أن المادة 4 من قانون الشراء العام قد نصت على ما يلي:\nكُنشئ الجهة الشارية سجلاًٌ خاصاً تُضئيّه كل المعلومات المتعلقة بعملية الشراءء ويَحمظ فيه جميع الوثائق\nالمتعلقة بإجراءات التلزيم ويّدٍ ملفات لها وتحافظ عليها . يمكن الاطلاع على هذا السجل وفقَا لأحكام هذه المادة\nويعتقد مرجع تسهل مراجعته واستقاء المعلومات منهء ويُحفظ الكترونباً في حال كان توقره ممكنا ...\"\nويما أن سجلَ إجراءات الشراء يعد أداة أساسية للشفافية والمساءلة إذ انّ الهدف الأساسي من فرضه هو:\nه تمكين الجهات الرقابية والناظرة بالنزاعات المرتبطة باجراءات الشراء من تتبّع مجريات عملية الشراء وفهم\nالأسس التي بُنيت عليها القرارات المتخذة.\nتوفير أثر توثيقي واضح يُظهر كيف ولماذا اتُخذت القرارات في كل مرحلة من مراحل الشراء .\nتكوين قاعدة معلومات تسهل الاحصاءات والبيانات لتسهيل اتخاذ القرارات وتصوبيها.\nظ وبما أنه وبالتالي» فإن السجل هو أداة حوكمة وتوثيق» وليس غاية شكلية بحدّ ذاته.\nويما أن 'سجل إجراءات الشراء\":\n٠ لا يُقصد به بالضرورة دفتراً ورقياً واحدأًء\n٠ وهو ليس دفترا تدوّن فيه كل المحتويات اللازمة لتكوين السجل؛\n٠ بل هو مجموعة منظّمة من المعلومات والوثائق التي تعكس مجربات عملية الشراء والقرارات المرتبطة\nبها؟\n٠ وهو يتضمن المستندات محفوظة بأرقام مرجعية بموضوعها (عنوانه) مدونة في مرجع يتخذ شكل الدفتر\nالورقي او الالكتروني؛\n٠ ويمكن أن يتخذ شكل ملفات إدارية (51195 176114©لا0106) أو نظام توثيق إلكتروني» شرط أن يحقّق"}, {"o": 1, "l": null, "b": "متطلبات الشفافية لة ١ الى ؟ مات ومراجعتها. .<« 2\nبات الشفافية وسهولة الوصول الى المعلومات ومراجعتها (رجمحورن سر\nوك وف 1\n7 4 صفحة 2/1\n0\n06 الجمهوريّة اللبنانيتة\nهت هيئة الشراء العام\nوبما أنه ولهذه الغاية» يشجّع المشرّع صراحة على اعتماد الوسائل الإلكترونية في حفظ سجلٌ إجراءات الشراء\nمت كان ذلك ممكناً؛ لما لذلك من ذو فى مهيل حت المعاومات ونهولة الوضول الديا ند الاقتاء والكد\nمن مخاطر فقدانها أو التلاعب بهاء وهو ما يتوافق مع التوجهات الحديثة في الإدارة العامة.\nويما أنه يستفاد مما تقدّم أنّ المقصود بسجلّ إجراءات الشراء» وفقاً لأحكام المادة /9/ من قانون الشراء العام\nرقم 7077/744, أنه إطار توثيقي شامل يضم جميع المعلومات والمستندات المتعلّقة بعملية الشراء» بما يتيح\nتتبّع مجرياتها ومراجعتها عند الاقتضاء»؛ دون أن يكون المشرّع قد فرض شكلاً مادياً أو وسيلة محدّدة لتنظيم\nكا السك\nلذلك»\nترى هيئة الشراء العام ان اعتماد ملفات إدارية منظّمة» ورقية و/أو إلكترونية» تتضمّن كامل الوثائق والمعلومات\nالمطلوبة» ويُتاح الرجوع إليها بسهولة» يُعَدَ متوافقاً مع نصّ القانون» طالما تحقّقت متطلبات الشفافية»؛ وحسن\nالتوثيق» وإمكانية الرقابة.\nلج دربو2 بيروت في 17؟١/75/.1١٠\nل\nسا د. جان افعطي\nملاحظة: يعمل بهذه المذكرة من تاريخ نشرها على المنصة الالكترونية لهيئة الشراء العام الذي يعتبر بمثابة تبليغ للجهات\nالشارية عملا بأحكام الفقرة 5 من المادة )١( من قانون الشراء العام.\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (143,'مذكرات الرئيس','مذكرة رقم 6/ه.ش.ع./٢٠٢٦ موجَّهة إلى كافَّة الجهات الخاضعة لأحكام قانون الشراء العام بموضوع تنظيم عقد بين الجهة الشارية والملتزم المؤقت','2026-01-27','https://www.ppa.gov.lb/ar/pages/details/143','{"https://admin.ppa.gov.lb/storage/listing-pages/files/DR0KnB8MWKgiycLMBy6Ie5Ajkitw53EjMuT4-1770102107.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/DR0KnB8MWKgiycLMBy6Ie5Ajkitw53EjMuT4-1770102107.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=143),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "06 الجمصوريّة اللبنانيتة\n2ك هيئةالشراء العام\nشفافية ٠ منافسة ٠ نزاهصة\nمذكرة رقم \"/ه.ش.ع./7 \"١7\nموجّهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام\nحول تنظيم عقد بين الجهة الشارية والملتزم\nبناءً على قانون الشراء العام رقم 4 4 ؟ تاريخ ٠١71/17/١5 المعدل بالقانون رقم \"٠١5 تاريخ 27١7/4/١9\nلاسيّما المادتين 5 و88 منه»\nوبما أن المادة 4 ؟ من قانون الشراء العام قد نصت في فقراتها 40765:5.4 على ما يلي:\n(5):\"فور انقضاء فترة التجميدء تقوم الجهة الشارية بابلاغ الملتزم المؤقت بوجوب توقيع العفد خلال مهلة لا\nتتعدى//ه ١ يوماً/ خمسة عشرة يوما\" ,\n(5): \" يوقّع المرجع الصالح لدى الجهة الشارية العقد خلال مهلة //ره //١ خمسة عشرة يومأ من تاريخ توقيع\nالعقد من قبل الملتزم المؤقت . يمك ن أن تُمدد هذه المهلة إلى //١ا// ثلاثين يوماً في حالات معيّنة تحدد من\nقبل المرجع الصالح\" .\n(1): \"يبدأ نفاذ العقد عندما يوقع الملتزم المؤقت والمرجع الصالح لدى سلطة التعاقد عليه \".\n(1):\" لا تتخذ سلطة التعاقد ولا الملتزم المؤقت أي إجراء يتعارض مع بدء نفاذ العقد أو مع تنفيذ الشراء خلال\nالفترة الزمنية الواقعة ما بين تبليغ العارض المعني بالتلزيم المؤقت وتاريخ بدء نفاذ العقد \".\n(1): \"في حال تمنّع الملتزم المؤقت عن توقيع العفدء تُصادر الجهة الشارية ضمان عرضه. في هذه الحالة يمكن\nللجهة الشارية أن تُلغي الشراء أ وأن تختار العرض الأفضل من بين العروض الأخرى الفائزة وفقاً للمعايير\nوالاجراءات المحتّدة في هذا القانون وفي ملفات التلزيم» والتي لا تزال صلاحيتها سارية المفعول. تُطبق\nاحكام هذه المادة على هذا العرض بعد إجراء التعديلات اللازمة \".\nوبما أن المادة ١؟ من قانون الشراء العام قد نصت في البند ثانياً (الكشوفات) على ما يلي:\nليجب أن يُحدد في شروط العقد ما يلي:"}, {"o": 1, "l": null, "b": ".١ \" وجوب تقديم الملتزم كشوفات السلع أو الخدمات أو الأعمال المنقذة على اختلافها ووجوب تصديقها\nمن قبل سلطة التقاعد»\n.١ المهلة القصوى المُعطاة للملتزم لإعداد هذه الكشوفات ومهل الموافقة عليها أو تعديلها من قبل سلطة\nالتعاقدء\n.٠“ المهلة القصوى لإصدا رأمر الدفع\".\nوبما أن المادة 77 من قانون الشراء العام قد نصت في فقرتها (7أ) وفقرتها (\"أ) على ما يلي:\n(1أ): \"\"تحدد شروط العقد طريقة الدفع بحسب مراحل التنفيذ أو بحسب المُنجزات» عل ىأن تتناسب الدفعات مع\nالفنجزاتء وعلى ألا تتجاوز تسعة أعشار المبلغ المستحقء ويبقى العشر موقوفاً في الخزينة إلى أن يتم\nالاستلام النهاني\" .\n(1أ): \" اليمكن أن يُجيز العقد لسلطة التعاقد إعطاء الملتزم سلفات لا تتخطى ,/٠١// عشرين بالمئة من قيمة\nالعقد على ألا تتجاوز في أي حال سقفاً محدداً ب 5 ١ مليار لير لبنانية يعد ل هذه السقف المالي بناة على\n0 اه\nا\n: 7“ الجمهوريّة اللبنائنيتة\n2582 صيئة الشراء العام\nلهك - شفافية ٠ منافسة ٠ه نزاهة\nتوصية من هيئة الشراء العام ويموجب مرسو ميُتخذ من مجلس الوزراء بناة على اقتراح رئيسهء على ألا\nيؤدي التعديل إلى مخالفة أهداف هذه المبادىء التي كرسها هذه القانون. يمكن لسلطة التعاقدء عند تجاوز\nالنسبة المحددة في هذه الفقرةء وفي حال نصّت ش روط العقد على ذلكء إعطاء الملتزم سلفات لقاء كفلات\nمصرفيةء وذلك بعد ابلاغ هيئة الشراء العام\".\nوبما أن المادة 7 من قانون الشراء العام قد نصت على ما يلي:\n\" يتوجب على الملتزم التقيّد بالمهل المحدّدة في العقد تحت طائلة دفع الغرامات المحددة فيه. ُفرض الغرامات\nبشكل حكمي على الملتزم بمُجرد مخالفته أحكام العقد دون حاجة لإثبات الضر ر\" .\nوبما أنه بالإستناد الى المواد 5 7/17377١7 السابق ذكرهاء فإن كل عمليّة شراء تنتهي الى عقد يكون المرجع\nالأساسي لتنفيذ عملية الشراء."}, {"o": 2, "l": null, "b": "وبما أنه تطبيقاً لهذه القاعدة» وبالرجوع الى دفاتر الشروط النموذجيّة المنشورة على المنصة الالكترونيّة\nالمركزية لدى هيئة الشراء العام؛ يتبيّن انها تتضمّن عدة أقسام منها ما يتعلق بتقديم العروض واجراءات التلزيم\nومنها ما يتعلق بشروط العقد العامة والخاصة وقد ألحق بها نموذج اتفاقية العقد (مشروع العقد المعد للتوقيع من\nطرفي التعاقد)\nلذلك\nتطلب هيئة الشراء العام من كافة الجهات الخاضعة لأحكام قانون الشراء العام تنظيم عقد بين الجهة الشارية\nوالملتزم باعتبار وثيقة العقد تشكل معاملة جوهرية يؤدي عدم الالتزام بها إلى عيب في عملية الشراء يوجب\nعدم السير بها,\n9 بيروت في 7١75/.1/11\n03 -- ا 1 0000\n2-2 ' رئيس هيئة الشراء العام\n4 ///\n|\n٠,١ 0 -_\n00\n4\nملاحظة: يعمل بهذه المذكرة من تاريخ نشرها على المنصة الالكترونية المركزية لدى هيئة الشراء العام الذي يُعتبر بمثابة تبليغ\nللجهات الشارية عملا بأحكام الفقرة 5 من المادة (؟) من قانون الشراء العام.\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (144,'مذكرات الرئيس','مذكرة رقم 7/ه.ش.ع/ 2026 موجهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام في موضوع تأمين الحاجات الأساسية والملحة في ظل الظروف الإستثنائية','2026-03-06','https://www.ppa.gov.lb/ar/pages/details/144','{"https://admin.ppa.gov.lb/storage/listing-pages/files/RBVgwau232FylYRmUcIuGltCT59eHStDrYtq-1772795808.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/RBVgwau232FylYRmUcIuGltCT59eHStDrYtq-1772795808.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=144),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /7هـ.ش.ع2026/\n موجهة إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n في موضوع تأمين الحاجات األساسية والملحة في ظل الظروف اإلستثنائية\n إن رئيس هيئة الشراء العام،\nبنا ًء على قانون الشراء العام رقم 244تاريخ 2021/7/19وتعديالته ،سيما المواد 46 ،42 ،41 ،14\n فقرة ( 77 ،76 ،)2و 88منه،\nوبالنظر الى الظروف اإلستثنائية الحالية التي تحول دون اعتماد بعض القواعد وطرق الشراء\n المنصوص عليها في المادتين 41و 42من قانون الشراء العام،\nوباإلستناد الى المادة 46فقرة ( )2من قانون الشراء العام التي أجازت استثنائيًا الشراء بواسطة إتفاق\nرضائي \"في حاالت الطوارىء واإلغاثة من جراء وقوع حدث كارثي وغير متوقع ونتيجة ذلك ال يكون\n استخدام أي طريقة شراء أخرى أسلوبًا عمليًا لمواجهة هذه الحاالت\"،\nوباإلستناد الى المادة 14فقرة (.1أ) من قانون الشراء العام التي أجازت للجهة الشارية تجزئة الشراء إلى\nكتنوع\n مبررات واضحة ّ أجزاء مستقلة \"عندما تتطلب ذلك طبيعة األعمال أو السلع أو الخدمات ،ووجود ّ\nمصادر التوريد وتعدّدها او اختالف األجزاء عن بعضها بما يؤدي الى منفعة أكيدة من التجزئة ،على أن\n بر ًرا وخاضعًا للرقابة وفقًا للقوانين المرعية اإلجراء\"،\n يكون القرار ُم ّ\nولتأمين حاجات اإلدارة األساسية وال ُمل ّحة ومنها على سبيل المثال ال الحصر (األدوية والمستلزمات\nالطبية ،ومستلزمات اإليواء وشراء المواد الغذائية والمحروقات ،رفع االنهيارات ،إزالة الردم ،ترميم\nالبُنى التحتية )....في هذه الظروف اإلستثنائية حيث ال يمكن تأمينها باعتماد الطرق العادية التنافسية مع\nما تستوجبه من إجراءات إعداد دفاتر الشروط واإلعالن عن الشراء والتقييم وإعالن النتيجة وانقضاء\n فترة التجميد،\n يوضح ما يلي:\nأول :يمكن التعاقد مباشرة ً باإلستناد إلى المادة 46من قانون الشراء العام في الحاالت اإلستثنائية حيث ال\n ً"}, {"o": 1, "l": null, "b": "يكون ممكنًا تأمين الحاجات األساسية والملحة بصورة فعالة باعتماد طريقة شراء أخرى وضمن حدود\n تأمين هذه الحاجات الضرورية.\nثانيًا :إن المادة 62من قانون الشراء العام المتعلقة بموجب النشر المسبق لمدة عشرة أيام ال تطبق في\nهذه الحالة سندًا للفقرة 2من هذه المادة التي تستثني من تطبيق النشر المسبق التعاقد الرضائي المسند الى\nالفقرتين ( )2و( )4من المادة 46من القانون عينه ،على أن يتم نشر العقود الناشئة عن هذا التعاقد عند\n عمال بأحكام المذكرة رقم /2هـ.ش.ع 2023/تاريخ .2023/2/16 زوال الظروف االستثنائية ً\n 1/2\n\fثالثًا :فيما يتعلق بالحاجات األساسية وال ُملحة المشار اليها أعاله والتي يعود أمر تقديرها لإلدراة المعنية\nوعلى كامل مسؤوليتها وفي حدود مصادر التمويل المتوفرة وفي ظل رقابة هيئة الشراء العام الالحقة،\nبررة استثنائيًا باعتبارات المصلحةيُمكن اجراء الشراء لمرات متعددة وان شكل ذلك تجزئة إال أنها ُم ّ\n العامة واستمرارية المرفق العام ضمن الحدود المنصوص عليها في المادة 14من قانون الشراء العام.\nرابعا ً :يُعمل بهذه المذكرة فور نشرها على الموقع االلكتروني لهيئة الشراء العام وتبقى سارية المفعول\n لحين صدور مذكرة ُمخالفة.\n بيروت في 2026/3/6\n رئيس هيئة الشراء العام\n د .جان العليًة\n 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (145,'قرارات الرئيس','قرار رقم 35 تاريخ 30-6-2026 تصديق موازنة هيئة الشراء العام لعام 2026','2026-06-30','https://www.ppa.gov.lb/ar/pages/details/145','{"https://admin.ppa.gov.lb/storage/listing-pages/files/1784800255-قرار رقم 35-2026 تصديق موازنة_0001.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1784800255-قرار رقم 35-2026 تصديق موازنة_0001.pdf"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (146,'مذكرات الرئيس','مذكرة رقم 8/ه.ش.ع./٢٠٢٦ موجّهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام حول الإفادات والمستندات التي يجب أن تتضمّنها دفاتر الشروط الخاصة من ضمن الشروط الإدارية','2026-09-24','https://www.ppa.gov.lb/ar/pages/details/146','{"https://admin.ppa.gov.lb/storage/listing-pages/files/1790336995-8-2026 الإفادات والمستندات التي يجب أن تتضمّنها دفاتر الشروط الخاصة من ضمن الشروط الإدارية_0001.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1790336995-8-2026 الإفادات والمستندات التي يجب أن تتضمّنها دفاتر الشروط الخاصة من ضمن الشروط الإدارية_0001.pdf"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (147,'دليل الأسئلة والأجوبة','دليلك السريع إلى الشراء العام (أسئلة وأجوبة)','2026-11-05','https://www.ppa.gov.lb/ar/pages/details/147','{"https://admin.ppa.gov.lb/storage/listing-pages/files/1795603158-Book5_PPA_QA_Document_AR_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795603158-Book5_PPA_QA_Document_AR_DIGITAL.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=147),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "إمسح الرمز لإلطالع على النسخة اإللكترونية لهذا الدليل\n\f\f\f\f المقدمة\nســؤاال وجوابــاً متكــرراً متعلّ قــاً بقانــون الشــراء العــام فــي لبنــان رقــم\n ً يجمــع هــذا المســتند ثمانيــة وســبعين ()78\nالمعنييــن ،فــي اإلحاطــة باإلطاريــن\n ّ والمدققيــن ،وســائرّ والمورديــن،\n ّ ،2021/244ويهــدف إلــى دعــم الجهــات الشــارية،\n القانونــي واإلجرائــي اللذيــن يحكمــان عمليــات الشــراء العــام فــي لبنــان.\nتســتند اإلجابــات الــواردة فــي هــذا المســتند إلــى أحــكام قانــون الشــراء العــام ،وإلــى المذكــرات الصــادرة عــن هيئــة\nـا عــن أفضــل الممارســات المعتمــدة ،وذلــك بهــدف تعزيــز مبــادئ الشــفافية ،وضمــان االمتثــال الشــراء العــام ،فضـ ً\n ألحــكام القانــون ،وتحقيــق الفعاليــة والكفــاءة فــي عمليــات الشــراء العــام.\n\f\f جدول المحتويات\n10 .Iالقسم األول :أسئلة عامة\n15 .IIالقسم الثاني :التحضير لعملية الشراء العام\n20 .IIIالقسم الثالث :القيمة التقديرية\n21 .IVالقسم الرابع :االجراءات المتّ بعة عند الشراء بالفاتورة\n23 .Vالقسم الخامس :التعاقد بالتراضي\n26 .VIالقسم السادس :طلب عروض االسعار\n27 .VIIالقسم السابع :خدمات استشارية\n28 .VIIIالقسم الثامن :االتفاق اإلطاري\n29 .IXالقسم التاسع :عقود الصيانة وقطع الغيار\n31 .Xالقسم العاشر :اجراءات التلزيم /ارساء العقود\n35 .XIالقسم الحادي عشر :استبعاد العارض/نكول الملتزم\n37 .XIIالقسم الثاني عشر :تحالف الشركات\n38 .XIIIالقسم الثالث عشر :تنفيذ عقود الشراء\n39 .XIVالقسم الرابع عشر :مشاركة العارضين االجانب\n40 .XVالقسم الخامس عشر :السرية ،الشفافية والنشر\n42 .XVIالقسم السادس عشر :تطبيقات عملية في تنفيذ قانون الشراء العام\n45 .XVIIمراجع مفيدة\n\f\f 10\n .Iالقسم األول :أسئلة عامة"}, {"o": 1, "l": null, "b": "الســــؤال .١مــا هــي معاييــر ومواصفــات مكاتــب التدقيــق الداخلي والتدقيق المســتقل لحســابات\n المؤسســات العامــة وحســابات المؤسســات والمرافق التابعــة للدولة؟\nالـــــــــجـــــــواب .يعتمــد فــي هــذا اإلطــار القــرار الصــادر عــن وزيــر الماليــة رقــم 1/355تاريــخ 2026/3/9بعــد اســتطالع\nرأي هيئــة الشــراء العــام (الــرأي رقــم /747ه.ش.ع 2025/.تاريــخ ،)2025/11/18والــذي يحــدد معاييــر\nومواصفــات مكاتــب التدقيــق الداخلــي والتدقيــق المســتقل لحســابات المؤسســات العامــة\n وحســابات المؤسســات والمرافــق التابعــة للدولــة.\nالممولــة مــن قبــل جهــات خارجيــة ألحــكام قانــون الشــراء\n ّ الســــؤال .٢هــل تخضــع المناقصــات\n العــام؟\nالـــــــــجـــــــواب .بحســب المــادة 3مــن قانــون الشــراء العــام ،تخضــع لعمليــات الشــراء العــام جميــع الصفقــات التــي\nتقــوم بهــا الجهــات الشــارية ،ســواء كان تمويلهــا مــن الموازنــة أو الخزينــة أو مــن قــروض داخليــة أو\nمقيــدة بشــروط الواهــب ،مــع مراعــاة أحــكام المعاهــدات واالتفاقيــات او خارجيــة أو مــن هبــات غيــر ّ\n الهبــات المبرمــة مــع الدولــة اللبنانيــة.\nالممولــة مــن قــروض خارجيــة تخضــع مــن حيــث المبــدأ لقانــون الشــراءّ بالتالــي ،فــان المناقصــات\nالعــام .إال أنــه ،وبصــورة اســتثنائية ،يمكــن تطبيــق أحــكام مغايــرة لتلــك المنصــوص عليهــا فــي هــذا\nنصــت اتفاقيــات القــرض أو الهبــة صراحـ ًـة علــى تطبيــق إجــراءات مختلفــة ،وعندهــا تُ عتمــد\n القانــون إذا ّ\n األحــكام الخاصــة المنصــوص عليهــا فــي تلــك االتفاقيــات.\nالســــؤال .٣فــي حــال وجــود تعــارض بيــن النظــام المالــي إلحــدى الجهــات الشــارية وأحــكام\n طبــق؟\n قانــون الشــراء العــامّ ،أيهمــا ُي َّ"}, {"o": 2, "l": null, "b": "الـــــــــجـــــــواب .فــي حــال وجــود أي تعــارض أو عــدم تطابــق بيــن النظــام المالــي للجهــة الشــارية وأحــكام قانــون\nالشــراء العــام رقــم ُ ،2021/244يعمــل بأحــكام قانــون الشــراء العــام باعتبــاره القانــون الواجــب التطبيــق\nواآلمــر ،والــذي يســمو علــى غيــره مــن النصــوص .اذ نصــت المــادة - 114فقــرة -5مــن قانــون الشــراء\n العــام علــى الغــاء كل نــص مخالــف ألحــكام هــذا القانــون او ال تتناســب مــع مضمونــه.\nحيــز التنفيــذ بتاريــخ 29تمــوز ،2022أصبــح قانــون الشــراء العــام اإلطــار القانونــي اإللزامي\n فمنــذ دخولــه ّ\nالــذي يحكــم جميــع عمليــات الشــراء المتعلّ قــة باللــوازم واألشــغال والخدمــات التــي تجريهــا الجهــات\nعمــا تضمنتــه القوانيــن أو المراســيم أو األنظمــة الداخليــة الســابقة الشــارية ،وذلــك بصــرف النظــر ّ\n مــن أحــكام مخالفــة.\nيتوجــب علــى الجهــة العامــة االلتــزام بتطبيــق ّ وبنــاء عليــه ،وفــي حــال عــدم تطابــق النصــوص، ً\nعــد\nاإلجــراءات وطــرق الشــراء والســقوف الماليــة المنصــوص عليهــا فــي قانــون الشــراء العــام ،وتُ ّ\nـا\n األحــكام المخالِ فــة الــواردة فــي أنظمتهــا ملغــاة حكمــاً وغيــر نافــذة ،دون حاجــة إلــى تعديلهــا تعديـ ً\n صريحــاً أو رســمياً.\n\f11\n ً\n اعتبارا من تشرين االول /أكتوبر 2024؟ الســــؤال .٤ما هي السقوف المالية الجديدة\nالـــــــــجـــــــواب .تــم تعديــل الســقوف الماليــة فــي بعــض المــواد القانونيــة اعتبــاراً مــن تشــرين االول 2024بموجــب\n المرســوم رقــم 14063تاريــخ 2024/10/3علــى النحــو التالــي:\n السقف الجديد (المرسوم رقم السقف السابق (المرسوم رقم\n المادة والموضوع\n 14063تاريخ )2024/10/3 11339تاريخ )2023/5/29"}, {"o": 3, "l": null, "b": "10مليارات ليرة لبنانية 5مليارات ليرة لبنانية المادة ( 11وضع خطط الشراء)\n المادة ،34الفقرة الثانية\n 5مليارات ليرة لبنانية 2.5مليار ليرة لبنانية\n (ضمان العرض)\n المادة ،37الفقرة الثالثة (أ)\n 15مليار ليرة لبنانية 5مليارات ليرة لبنانية\n (دفع قيمة العقد)\n المادة ( 44شروط استخدام طلب\n 15مليار ليرة لبنانية 5مليارات ليرة لبنانية\n عروض األسعار)\n المادة ( 47شروط التعاقد\n 1.5مليار ليرة لبنانية 500مليون ليرة لبنانية\n بالفاتورة)\n ّ\n مستقلة؟ الســــؤال .٥في أي حال يجوز للجهة الشارية تجزئة الشراء إلى أجزاء\n الـــــــــجـــــــواب .نصت"}, {"o": 4, "l": "المادة 14", "b": "المادة 14من قانون الشراء العام على ما يلي:\n « .1يجوز للجهة الشارية تجزئة الشراء إلى أجزاء مستقلة في الحالتين التاليتين فقط:\n كتنّوع\n ّ أ .عندما تتطَّلّ ب ذلك طبيعة األعمال أو السلع أو الخدمات ،ووجود مب ِّّررات واضحة\nوتعُّددهــا أو اخــتالف األجــزاء عــن بعضهــا بمــا يــؤدي إلــى منفعــة أكيــدة مــن ّ مصــادر التوريــد\n التجزئــة ،علــى أن يكــون القــرار مب ـ َّّررًاً وخاضعــًاً للرقابــة وفقــًاً للقوانيــن المرعيــة اإلجــراء.\n ب .عند تنفيذ سياسات تنموية للحكومة كتشجيع مشاركة المؤسسات الصغيرة والمتوسطة\n في الشراء العام.\n بَغ ََرض تخفيض القيمة « .2ال يجوز تجزئة الشراء إلى جزئيات لتطبيق أحكام خاصة بكل جزء منها َ\nالتقديريــة لمشــروع الشــراء أو بقصــد التهـ ّـّرب مــن الرقابــة أو مــن تطبيــق أحــكام هــذا القانــون أو\n القوانيــن واألنظمــة األخــرى».\n ً\n وفقا لقانون الشراء العام؟ الســــؤال .٦متى يجوز للجهة الشارية إلغاء المناقصة أو المزايدة\nالـــــــــجـــــــواب .ال يجــوز للجهــة الشــارية إلغــاء المناقصــة أو المزايــدة ألي ســبب ،إذ إن حــاالت اإللغــاء محــددة حصــراً\n فــي المــادة 25مــن قانــون الشــراء العــام.\n\f 12\n أوال :يجوز للجهة الشارية إلغاء الشراء و/أو أي من إجراءاته في الحاالت التالية:\n ً\n متوقعة على ملفات التلزيم بعد اإلعالن؛\n ّ • إذا استدعى األمر إدخال تغييرات جوهرية غير\n متوقعة ّأثرت على موازنة الجهة الشارية؛\n ّ • إذا طرأت تغييرات غير\n متوّقعة (وفي هذه\n ّ • إذا انتفت الحاجة لموضوع الشراء بسبب ظروف موضوعية وغير\n الحالة ال يجوز إعادة التلزيم خالل السنة المالية نفسها)؛\n قدم أي عرض أو إذا كانت جميع العروض غير مقبولة. • إذا لم ُي َّ\n ثانياً :حالة العارض الوحيد المقبول\n تقدم عارض واحد فقط.\n القاعدة :على الجهة الشارية إلغاء الشراء إذا ّ"}, {"o": 5, "l": "المادة 14", "b": "االســتثناء :يجــوز للجهــة الشــارية عــدم اإللغــاء واالســتمرار بالتلزيــم فقــط إذا توافــرت الشــروط\n الثالثــة التاليــة مجتمعــة:\n • أن تكون إجراءات الشراء مطابقة لقانون الشراء العام ،وأال يكون العرض الوحيد ناتجًاً عن\n شروط حصرية أو مقِّيِ دة للمنافسة؛\n وملحة ،وأن يكون السعر متناسباً مع القيمة التقديرية؛\n ّ • أن تكون الحاجة أساسية\n • أن يصدر قرار معلّ ل بقبول العرض الوحيد ،وأن ُينشر هذا القرار وفق األصول.\n إذا لم تتوافر هذه الشروط مجتمعة ،يجب إلغاء المناقصة أو المزايدة.\nيمكــن الرجــوع الــى مذكــرة هيئــة الشــراء العــام رقــم 2026/4تاريــخ 2026/1/27بموضــوع العــرض\n المرتفــع ســعره بشــكل غيــر اعتيــادي.\n يتم اإللغاء؟\n ثالثاً :كيف ّ\n عند اتخاذ قرار اإللغاء ،يجب على الجهة الشارية:\n •تعليل القرار خطياً وتسجيله ضمن إجراءات الشراء؛\n •تبليغ جميع العارضين خالل مهلة ال تتجاوز خمسة أيام؛\n •نشر قرار اإللغاء بالطريقة نفسها التي نُ شر فيها إعالن الشراء؛\n •إعادة العروض غير المفتوحة وتحرير الضمانات.\nوال تترتــب علــى الجهــة الشــارية أي مســؤولية تجــاه العارضيــن عنــد اإللغاء ضمن الحــاالت القانونية،\n وال يجــوز فتــح أي عــرض بعــد صــدور قــرار اإللغاء\nيطبــق قانــون الشــراء العــام فــي حالــة تأجيــر أو اســتثمار مســاحات أو منشــآت\n ّ الســــؤال .٧متــى\nعائــدة لجهــة شــارية أو منــح «ترخيــص باإلشــغال»؟ ومتــى يمكــن الخــروج عــن هــذا\n اإلطــار؟\nطبــق قانــون الشــراء العــام عندمــا تقــوم جهــة عامــة بتأجيــر أمــاك تملكهــا ،كاألراضــي أو المبانــيُي َّ الـــــــــجـــــــواب.\nأو الشــقق ،إلــى طــرف خــاص ،ويجــب أن تتـ ّـم وفــق إجــراء تنافســي ،المزايــدة العمومية ،بما ينســجم\n مــع أحــكام قانــون الشــراء العــام.\n\f13"}, {"o": 6, "l": "المادة 14", "b": "كقاعــدة عامــة ،ومــع االخــذ بعيــن االعتبــار مــا تضمنــه قانــون تنظيــم الشــراكة بيــن القطــاع العــام\nوالقطــاع الخــاص رقــم 2017/48وتعديالتــه ،عنــد االنطبــاق ،يخضــع تأجيــر ،أو ادارة ،او اســتثمار\nـا بالقــرار التشــريعي رقــم 275تاريــخ 25أمــاك الدولــة ،أو القطــاع العــام إلجــراء مزايــدة عموميــة ،عمـ ً\nطبــق علــى هــذه المزايــدة األحــكام\n أيــار ســنة ( 1926ادارة وبيــع أمــاك الدولــة الخصوصيــة) ،علــى أن تُ َّ\n االجرائيــة المنصــوص عليهــا فــي قانــون الشــراء العــام.\nورد فــي المــادة 60مــن القــرار 1926/275مــا يلــي« :ان العقــارات الداخلــة فــي أمــاك الدولــة فــي\nتؤجــر بعــد االعــان عنهــا لمــدة أربــع ســنوات علــى االكثــر وبنــاء علــى تعييــن ســعر افتتــاح\n المــدن ّ\n المزايــدة علــى أثــر كشــف اداري.\nتؤجــر فيهــا العقــارات إلدارة عموميــة أو لمصلحــة للمنفعــة العموميــة أو فيمــا عــدا االحــوال التــي ّ\nالحــد البلديــات يجــب بصــورة اجباريــة أن يجــري التأجيــر بالمــزاد العلنــي .إذا لــم ينجــح المــزاد فيمكــن\n اجــراء التأجيــر بالرضــى».\nالســــؤال .٨هــل تخضــع عمليــات شــراء ســندات الخزينــة مــن قبــل الجهــات الشــارية ألحــكام قانــون\n الشــراء العــام؟\nالـــــــــجـــــــواب .ال تُ عتبــر عمليــات شــراء ســندات الخزينــة مــن قبــل الجهــات الشــارية مــن عمليــات الشــراء العــام ،بــل\nتُ صنَّ ــف كعمليــات اســتثمار مالــي .وبالتالــي ،فهــي ال تخضــع ألحــكام القانــون رقــم ،2021/244علــى\nأن تتــم فــي إطــار سياســة اســتثمارية معتمــدة ووفقــاً لألنظمــة الماليــة والقانونيــة المعمــول بهــا.\nالســــؤال .٩هــل يمكــن لجهــة شــارية تمتلــك معــدات غيــر صالحــة لالســتعمال أن تعيــد هــذه\n ّ"}, {"o": 7, "l": "المادة 14", "b": "للتخلــص منهــا ،دون اللجــوء إلــى مزايــدة ً\n مجانــا المــوردة\n ِّ المعــدات إلــى الشــركة\n لبيعهــا؟\nـوردة مجانــاً للتخلّ ــص منهــا دون اتبــاعالـــــــــجـــــــواب .كال ،ال يجــوز للجهــة الشــارية إعــادة المعــدات إلــى الشــركة المـ ِّ\nاإلجــراءات القانونيــة المنصــوص عليهــا فــي قانــون الشــراء العــام .فوفقــاً ألحــكام القانــون ،يجــب أن\nتتـ ّـم عمليــة التصــرف بالمعــدات التــي تملكهــا الجهــة الشــارية ،متــى كانــت تُ عـ ّـد مــن األصــول العائــدة\n لهــا ،مــن خــال مزايــدة علنيــة.\nالتصــرف فــي األصــول\n ّ تنظــم\n عــد مخالفــاً للقواعــد التــي ّ إن التخلّ ــص مــن المعــدات دون مقابــل ُي ّ\nالثابتــة ،إذ يقتضــي األمــر إثبــات مصلحــة الجهــة الشــارية فــي هــذا التصـ ّـرف ،وبيــان الضــرر أو الخســارة\nـاء عليــه ،يتوجــب علــى الجهــة الشــاريةالمترتبــة علــى خيــار عــدم بيــع هــذه المعــدات عبــر المزايــدة .وبنـ ً\nااللتــزام باإلجــراءات القانونيــة المتعلقــة بالمزايــدات ،بمــا يضمــن تحصيــل مقابــل مالــي عــن المعــدات\n غيــر القابلــة لالســتعمال او اثبــات عــدم وجــود قيمــة بيعيــة لهــا.\nالسـؤال .١٠هــل يخضــع الشــراء الــذي يهــدف إلــى منــح أي التــزام أو امتيــاز الســتغالل مــورد مــن\nمــوارد ثــروة البــاد الطبيعيــة ،أو مصلحــة ذات منفعــة عامــة ،أو أي احتــكار ،وكذلــك\n اإلجــراءات التــي تســبق منــح االمتيــاز أو االحتــكار ،لقانــون الشــراء العــام؟\nالـــــــــجـــــــوابُ .يســتثنى مــن أحــكام قانــون الشــراء العــام الشــراء الــذي يهــدف إلى منــح أي التزام أو امتياز الســتغالل\n مــوارد ثــروة البــاد الطبيعيــة ،أو مصلحــة ذات منفعــة عامة ،أو أي احتكار.\n\f 14"}, {"o": 8, "l": "المادة 14", "b": "ومــع ذلــك ،فــإن اإلجــراءات التــي تســبق منــح االمتيــاز أو االحتــكار تخضــع للمبــادئ العامــة المنصــوص\nعليهــا فــي المــادة األولــى مــن قانــون الشــراء العــام ،وذلــك فــي حــدود مــا ال يتعــارض مــع أي نصــوص\nخاصــة واردة فــي قوانيــن أخــرى (الفقــرة ٤مــن المــادة -٣نطــاق التطبيــق -مــن قانــون الشــراء العــام).\n ّ\nتنظمــه البلديــة السـؤال .١١هــل يخضــع إشــراك عارضيــن أو مشــاركين فــي فعاليــة أو معــرض\nألحــكام قانــون الشــراء العــام ،ومــا هــو اإلطــار القانونــي الواجــب اعتمــاده لضمــان\n االمتثــال لمبــادئ الشــراء العــام؟\nـراء مــن\n الـــــــــجـــــــواب .إن إشــراك عارضيــن أو مشــاركين فــي فعاليــة أو معــرض تنظمــه البلديــة ال ُيعــد بحــد ذاتــه إجـ ً\nإجــراءات الشــراء العــام وال يشــكّ ل صفقــة لــوازم أو خدمــات أو أشــغال خاضعــة لقانــون الشــراء العــام،\nطالمــا أن البلديــة ال تقــوم بشــراء خدمــات مــن هــؤالء العارضيــن ،بــل تتيــح لهــم المشــاركة فــي نشــاط\n عــام مقابــل بــدل اشــتراك ُيســتوفى لقــاء خدمــة مؤقتــة.\nطبــق حصــراً علــى المشــتريات التــي تقــوم بهــا البلديــة نفســها لتنظيــم\n في ّ\n أمــا قانــون الشــراء العــام ُ\nالفعالية ،مثل شــراء اللوازم ،أو تلزيم األشــغال ،أو التعاقد على الخدمات (كالزينة ،اإلنارة ،الخدمات\nاللوجســتية ،العــروض الفنيــة ،وغيرهــا) ،وذلــك وفقــاً لطبيعــة كل صفقــة وقيمتهــا وطريقــة التلزيــم\n المعتمــدة قانونــاً.\nالسـؤال .١٢فــي حــال التلزيــم علــى أســاس مجموعــات ،هــل يمكــن التفــاوض علــى مجموعــة\n واحــدة أو إلغاءهــا؟\nيحظــر التفــاوض مــع العارضيــن بشــأن العــروض التــي قدموهــا بحســب المــادة 56مــن قانــون الشــراء ّ الـــــــــجـــــــواب."}, {"o": 9, "l": "المادة 14", "b": "العــام .مــن ناحيــة اخــرى ،مــن الممكــن إلغــاء مجموعــة مــن عمليــة الشــراء فــي الحــاالت المحــددة فــي\n المــادة ٢٥مــن قانــون الشــراء العــام.\n\f15\n .IIالقسم الثاني :التحضير لعملية الشراء العام\nً\nوفقــا السـؤال .١٣مــا هــي المتطلبــات القانونيــة المتعلقــة بلغــة ملفــات التلزيــم والمراســات\n لقانــون الشــراء العــام؟\nالـــــــــجـــــــواب .إن اللغــة العربيــة هــي اللغــة اإللزاميــة لجميــع ملفــات التلزيــم والقــرارات الصــادرة عــن الجهــة الشــارية\n وذلــك ســنداً لنــص المــادة 4مــن قانــون الشــراء العــام.\nيمكــن اعتمــاد اللغــة اإلنكليزيــة و/أو اللغــة الفرنســية إلــى جانــب اللغــة العربيــة فــي المراســات،\nأن القانــون ينـ ّـص صراحـ ًـة علــى أنّ ــه ،فــي\n وفــي إعــداد المواصفــات الفنيــة أو الشــروط المرجعيــة .غيــر ّ\nحــال وجــود أي تعــارض أو اختــاف بيــن النصــوصُ ،يعتـ ّـد بالنــص العربــي ويكــون هــو المرجــع المعتمــد\n (المــادة 4مــن قانــون الشــراء العــام).\nويســري هــذا االلتــزام علــى جميــع مراحــل عمليــة الشــراء العــام ،بحيــث ال يقتصــر علــى ملفــات التلزيــم\nالمعـ ّـدة بعد فـ ّـض العروض،والقــرارات التعاقديــة فحســب ،بــل يشــمل أيضــاً جميــع التقاريــر والمحاضــر ُ\nويشــترط أن تُ عـ ّـد هــذه المســتندات باللغــة\n بمــا فــي ذلــك تقاريــر تقييــم العــروض وتوصيــات اإلحالــةُ .\nالعربيــة ،علــى أن يجــوز إعــداد ترجمــات إلــى لغــات أخــرى علــى ســبيل االســتئناس أو كنســخ مســاندة،\n دون أن تحـ ّـل محـ ّـل النــص العربــي أو ان تتفـ ّـوق عليــه.\nالسـؤال .14كيــف تُ عالــج الحالــة التــي قــد يســتحيل فيهــا علــى العارضيــن توفيــر بعــض المســتندات\n المطلوبــة وفقـ ًـا لقانــون الشــراء العــام؟"}, {"o": 10, "l": "المادة 14", "b": "أوال ،مــن قانــون الشــراء العــام تتطلــب شــروط مشــاركة العارضيــن توفيــر الـــــــــجـــــــواب .بمقتضــى المــادة ،7البنــد ً\nتوفــر كل شــرط لــدى العــارض .اســتناداً إلــى ذلــك ،أصــدرت هيئــة الشــراء العــام\n مســتندات تثبــت صحــة ّ\nالمذكــرة رقــم /8ه.ش.ع 2023/.بتاريــخ ،2023/12/12والتــي تحــدد المســتندات المطلوبــة لالشــتراك\n فــي الصفقــات العموميــة أو عمليــات الشــراء العــام ســنداً لهــذه المــادة.\nمراعــاة لمقتضيــات التنميــة\n ً قــد تتيــح بعــض عمليــات الشــراء العــام ،بالنظــر إلــى طبيعتهــا أو\nورغبــة فــي إشــراك أكبــر عــدد مــن المؤسســات الصغيــرة والمتوســطة واألشــخاص ً المســتدامة\n مجــاال للتعاقــد مــع عارضيــن قــد ال يســتطيعون توفيــر بعــض المســتندات ،مثــل:ً الطبيعييــن،\n •إفادة عدم اإلفالس.\n •إفادة التسجيل في السجل التجاري لمن ال يمتلك صفة التاجر.\nوفــي هــذه الحــاالت ،فــإن طلــب مثــل هــذه المســتندات مــن عارضيــن ال يمكنهــم قانونيــاً أو عمليــاً\nتأمينهــا قــد يحــول دون اشــتراكهم فــي الشــراء العــام ،وهــو مــا يتعــارض مــع أحــكام المــادة األولــى\n مــن قانــون الشــراء العــام التــي تهــدف إلــى تشــجيع التنميــة المحليــة.\nوبنــاء عليــه ،فانــه فــي بعــض حــاالت الشــراء ،يجــب عــدم طلــب المســتندات التــي يســتحيل علــى\n ً\n العارضيــن تأمينهــا نظــراً لوضعهــم القانونــي.\n\f 16\nالسـؤال .15هــل يمكــن إعفــاء الشــركات التــي يكــون مالكوهــا هــم أنفســهم العامليــن فيهــا،\nـجلة حكمـ ًـا فــي الصنــدوق الوطنــي للضمــان\n والتــي ال تســتخدم أي أجــراء وغيــر مسـ ّ\nاالجتماعــي ،مــن تقديــم بــراءة ذمــة مــن الصنــدوق للمشــاركة فــي المناقصــات أو\n المزايــدات؟"}, {"o": 11, "l": "المادة 14", "b": "المســجلة حكمــاً فــي الصنــدوق الوطنــي\n ّ الـــــــــجـــــــواب .يمكــن إعفــاء الشــركات التــي ال تســتخدم أجــراء وغيــر\nويكتفــى فــي هــذه الحالــة بإفــادة صــادرة عــن الصنــدوقللضمــان االجتماعــي مــن تقديــم بــراءة ذمــةُ ،\n تثبــت عــدم تســجيل الشــركة لديــه ،وذلــك شــرط توافــر األمريــن التالييــن مجتمعيــن:\n شكال وواقعاً قانونياً على وضع الشركة؛\n ً •أن يكون عدم التسجيل منطبقاً\n •أن تكون طبيعة المشروع قابلة للتنفيذ دون استخدام أجراء.\n وفي حال عدم توافر هذين الشرطين ،يبقى موجب تقديم براءة الذمة قائماً.\nالسـؤال .16مــا هــو البديــل القانونــي عــن إفــادة البلديــة بالنســبة للشــركات التــي يقــع مركزهــا\n الرئيســي فــي قــرى ال توجــد فيهــا بلديــات؟\nالـــــــــجـــــــواب .فــي حــال كان المركــز الرئيســي للشــركة واقعــاً فــي بلــدة ال توجــد فيهــا بلديــة ،يمكــن اعتمــاد إفــادة\nصــادرة عــن وزارة الداخليــة والبلديــات – مديريــة شــؤون اإلدارات والمجالــس المحليــة ،تثبــت عــدم\nوجــود بلديــة فــي البلــدة المعنيــة ،وذلــك كبديــل قانونــي عــن إفــادة البلديــة المطلوبــة ضمــن ملفــات\n المشــاركة فــي إجــراءات الشــراء العــام.\nالسـؤال .17مــا هــو الغــرض مــن الضمــان المؤقــت (أو ضمــان العــرض) فــي إطــار قانــون الشــراء\n ـم مصادرتــه؟العــام ،ومتــى تتـ ّ\nالـــــــــجـــــــواب .الضمــان المؤقــت ،أو مــا ُيعــرف بضمــان العــرض ،هــو أداة قانونيــة تُ قـ َّـدم من العارضين عند المشــاركة\nجديــة العــارض والتزامــه بعرضــه خــال الفتــرة\n فــي إجــراءات الشــراء العــام ،وهدفــه األساســي ضمــان ّ\n الواقعــة بيــن تقديــم العــرض وبــدء نفــاذ العقــد.\nويعــاد إلــى"}, {"o": 12, "l": "المادة 14", "b": "ُيحـ َّـدد الضمــان المؤقــت بنســبة ال تتعــدى %3مــن القيمــة التقديريــة لعمليــة الشــراءُ ،\nالعارضيــن غيــر الفائزيــن بعــد انتهــاء إجــراءات التلزيــم ،بينمــا ُيســتبدل بضمــان حســن التنفيــذ للعــارض\n الــذي رســت عليــه الصفقــة عنــد توقيــع العقــد (المــادة 34مــن قانــون الشــراء العــام).\nتتــم مصــادرة الضمــان المؤقــت إذا امتنــع العــارض الفائــز عــن توقيــع العقــد بعــد تبلّ غــه قــرار التلزيــم\nالمؤقــت وخــال المهلــة القانونيــة المحــددة ( 15يومــاً قابلــة للتمديــد إلــى 30يومــاً فــي حــاالت\nمعينــة) ،علــى ان تقــوم الجهــة الشــارية بمصــادرة الضمــان لصالــح الخزينــة (المــادة - 24فقــرة -8مــن ّ\n قانــون الشــراء العــام).\nطبــق عليــه أحــكام الفســخ والنكــول المنصــوص\n بعــد توقيــع العقــد ،يصبــح العــارض «ملتزمــاً » وتُ َّ\n عليهــا فــي المــادة 33مــن قانــون الشــراء العــام فــي حــال اإلخــال بشــروط التنفيــذ.\n\f17\n ً\nإلزاميــا علــى الجهــة الشــارية تحديــد نــوع المناقصــة فــي دعــوة التأهيــل عــد\n السـؤال .18هــل ُي ّ\n المســبق؟\nالـــــــــجـــــــواب .نعــمُ ،يعـ ّـد مــن اإللزامــي أن تُ ّبيــن الجهــة الشــارية فــي دعــوة التأهيــل المســبق نــوع المناقصــة التــي\nســتُ عتمد فــي المرحلــة الالحقــة (مناقصــة علــى مرحلتيــن ،علــى ســبيل المثــال) ،وذلــك تعزيــزاً لمبــدأ\nالشــفافية ،وتمكينــاً للعارضيــن المحتمليــن مــن اإلحاطــة المســبقة بكامــل اإلجــراءات والخطــوات\n التــي ســيتم اعتمادهــا الحقــاً ،وعلــى أساســها يقـ ّـررون المشــاركة فــي المناقصــة مــن عدمهــا.\nالسـؤال .19هــل يمكــن اعتبــار اختبــارات إثبــات المفهــوم ( )Proof of Conceptمــن ضمــن معاييــر\n التأهيــل المســبق؟"}, {"o": 13, "l": "المادة 14", "b": "الـــــــــجـــــــواب .ال يمكــن اعتبــار اختبــارات إثبــات المفهــوم ( )Proof of Conceptمــن ضمــن معاييــر التأهيــل المســبق،\nإن هــذه االختبــارات ،وكذلــك آليــات إجرائهــا ،تُ عـ ّـد جــزءاً مــن وصــف موضــوع الشــراء ،وتنــدرج ضمــنإذ ّ\nـرة بموضــوع\n يقدمــه العــارض اســتناداً إلــى المواصفــات الفنيــة ،وترتبــط مباشـ ً العــرض الفنــي الــذي ّ\n الشــراء ذاتــه.\nللتحقــق مــنّ أن المعاييــر واإلجــراءات المعتمــدة تنــص المــادة 19مــن قانــون الشــراء العــام علــى ّّ\nمؤهــات العارضيــن يجــب أن تكــون منســجمة مــع أحــكام المــادة 7مــن القانــون نفســه ،والتــي تركّ ــز\n علــى مؤهــات العارضيــن ،وال سـ ّـيما الكفــاءة المهنيــة ،والقــدرات الماليــة ،والمعــدات ،والخبــرة.\nكمــا تنـ ّـص المــادة 17مــن القانــون ذاتــه علــى وجــوب تحديــد أوصــاف موضــوع الشــراء اســتناداً إلــى\nالخصائــص الفنيــة والوظيفيــة المطلوبــة وطــرق االختبــار ،علــى أن يتـ ّـم ذلــك ضمــن العــرض الفنــي\n المقـ َّـدم مــن العــارض.\nالسـؤال .20مــا هــو القيــد الــذي يفرضــه قانــون الشــراء العــام بشــأن اإلشــارة إلــى عالمــات تجاريــة\n أو أســماء تجاريــة عنــد وصــف موضــوع الشــراء؟\nالـــــــــجـــــــواب .نصــت الفقــرة 4مــن المــادة 17مــن قانــون الشــراء العــام علــى مــا يلــي« :ال يمكــن أن ُيشــير وصــف\nموضــوع الشــراء إلــى عالمــة تجاريــة معينــة أو اســم تجــاري أو بــراءة اختــراع أو تصميــم أو نــوع أو\nمعيــن أو إدراج إشــارة إلــى أي منهــا ،إال فــي الحالــة التــي يســتحيل معهــا\n ّ معيــن أو منتــج\n ّ منشــأ\nوصــف موضــوع الشــراء بطريقــة أخــرى دقيقــة ومفهومــة بمــا يكفــي لوصــف الخصائــص ،عندهــا\n ُيرفــق بعبــارة «أو مــا يعادلهــا»»."}, {"o": 14, "l": "المادة 14", "b": "ويهــدف هــذا القيــد إلــى ضمــان المنافســة العادلــة بيــن العارضيــن ومنــع التفضيــل ألي منتــج أو\n محــدد ،مــع المحافظــة علــى دقــة وصــف خصائــص ومواصفــات موضــوع الشــراء. ّ مــورد\n ّ\nالسـؤال .21مــا هــي طريقــة التلزيــم القانونيــة المعتمــدة إلجــراء الدراســات الهندســية أو الفنيــة\n فــي حــال عــدم توافــر القــدرات البشــرية أو الفنيــة الكافيــة لــدى الجهــة الشــارية؟\nالـــــــــجـــــــواب .تُ عـ ّـد الدراســات الهندســية أو الفنيــة مــن الخدمــات االستشــارية بالمعنــى المقصــود فــي المــادة 2\n-فقــرة -11مــن قانــون الشــراء العــام رقــم ،2021/244كونهــا خدمــات يغلــب عليهــا الطابــع الفكــري\nأو المهنــي ،وتشــمل علــى ســبيل المثــال ال الحصــر الدراســات الهندســية ،وأعمــال التصميــم ،وإعــداد\n المواصفــات ،والتقييــم ،واإلشــراف.\n\f 18\n يمكن للجهة الشارية اعتماد إحدى الطرق الشراء التالية:\n • الشراء بالفاتورة ،إذا كانت القيمة التقديرية للخدمة ،بما فيها الخدمات االستشارية ،ال\n تتجاوز مليارًاً وخمسمئة مليون ليرة لبنانية (السقف المالي للشراء بالفاتورة محَّدَ د ب\n //1.5//مليار ليرة لبنانية بحسب"}, {"o": 15, "l": "المادة 47", "b": "المادة 47من قانون الشراء العام والمرسوم رقم 14063\n تاريخ .)2024/10/3\n • طلب عروض األسعار ،إذا كانت القيمة التقديرية ال تتجاوز خمسة عشر مليار ليرة لبنانية\n محَّدد ب /15/مليار ليرة لبنانية\n ّ (السقف المالي للشراء بواسطة طلب عروض األسعار\n بحسب"}, {"o": 16, "l": "المادة 44", "b": "المادة 44من قانون الشراء العام والمرسوم رقم 14063تاريخ .)2024/10/3\n • طلب اقتراحات للخدمات االستشارية ،في الحاالت األخرى التي تتجاوز فيها القيمة\n السقوف المحددة أعاله أو عندما تقتضي طبيعة الخدمة اعتماد تقييم نوعي وفني\n معّمق.\n ّ\nويتــرك للجهــة الشــارية اختيــار طريقــة التلزيــم األنســب ،علــى أن يتــم ذلك اســتناداً إلــى طبيعة الخدمة\n ُ\nوقيمتهــا ،ومــع االلتــزام بمبــادئ الشــفافية والمنافســة وحســن إدارة المــال العــام المنصــوص عليهــا\n فــي قانــون الشــراء العام.\nالسـؤال .22مــا هــي اإلجــراءات الواجــب اتباعهــا إلجــراء مزايــدة عموميــة مــن قبــل جهــة خاضعــة\n لقانــون الشــراء العــام؟\nالـــــــــجـــــــواب .تخضــع المزايــدات العموميــة التــي تجريهــا الجهــات الخاضعــة لقانــون الشــراء العــام لألحــكام االجرائيــة\nـا بقانــون الشــراء العــام رقــم 2021/244 المطبقــة علــى المناقصــات العموميــة ،وذلــك عمـ ًّ نفســها\nومذكــرات هيئــة الشــراء العــام ذات الصلــة .تُ عتمــد اإلجــراءات التاليــة عنــد إجراء مزايــدة عمومية ،دون\n اإلخــال باألحــكام األخــرى المنصــوص عليهــا فــي القوانيــن ذات الصلــة ،وال ســيما قانــون البلديــات:\n عمال ب"}, {"o": 17, "l": "المادة 11", "b": "المادة 11من قانون الشراء العام.ً .1إدراج المزايدة في المخطط السنوي،\n .2تكليف لجنة تخمين لتحديد القيمة التقديرية وتحديد سعر االفتتاح ،وفقًاً للمادة 13من\n قانون الشراء العام.\n عمًال بالمادتين 51و 52من قانون الشراء ً .3إعداد دفتر شروط خاص بالمزايدة العمومية،\n العام.\n .4اإلعالن عن المزايدة العمومية وفقًاً ألحكام المواد 49و 50و 12من قانون الشراء العام،\n على أن يتضمن اإلعالن سعر االفتتاح.\n .5تأليف لجنة التلزيم وفقًاً للمادة 100من قانون الشراء العام وقرارات هيئة الشراء العام\n ذات الصلة.\n .6تسلّ م العروض وتحفظ وفقاً ألحكام"}, {"o": 18, "l": "المادة 53", "b": "المادة 53من قانون الشراء العام.\n عمال ب"}, {"o": 19, "l": "المادة 54", "b": "المادة 54من القانون\n ً .7فتح العروض وجرد المستندات وفحصها من قبل لجنة التلزيم،\n والدليل اإلرشادي الصادر عن هيئة الشراء العام.\n .8تقييم العروض من قبل لجنة التلزيم وفقًاً للمادة 55من قانون الشراء العام والدليل\n اإلرشادي.\n .9تحديد الملتزم المؤقت من قبل لجنة التلزيم وفقًاً للدليل اإلرشادي الصادر عن هيئة الشراء\n العام.\n عمال بالفقرة 2من"}, {"o": 20, "l": "المادة 24", "b": "المادة 24من قانون الشراء العام. ً .10نشر قرار قبول العرض الفائز\n .11تطبيق فترة التجميد المنصوص عليها في الفقرة 2من"}, {"o": 21, "l": "المادة 24", "b": "المادة 24من القانون.\n\f19\n .12دعوة الفائز المؤقت لتوقيع العقد وفقاً للفقرة 4من"}, {"o": 22, "l": "المادة 24", "b": "المادة 24من قانون الشراء العام.\n .13إجراء الرقابات والمصادقات المطلوبة قانوناً.\n .14توقيع العقد من المرجع الصالح وفقاً للفقرة 5من"}, {"o": 23, "l": "المادة 24", "b": "المادة 24من قانون الشراء العام.\n .15بدء نفاذ العقد ،اعطاء الملتزم أمر المباشرة بالعمل ودعوته إلى إيداع التأمين النهائي.\n السـؤال .23في مرحلة التأهيل المسبق ،هل يمكن مصادرة مبلغ ضمان العرض؟\nتطبــق أحــكام التأهيــل المســبق المنصــوص عليهــا فــي المــواد 19و 20و 21مــن قانــون الشــراء العــام.\n ّ الـــــــــجـــــــواب.\nيجــب االلتــزام بهــذه األحــكام ،وال يجــوز تطبيــق أي إجــراءات تتعــارض معهــا أو مصــادرة الضمــان خــارج\n الحــاالت المنصــوص عليهــا فــي قانــون الشــراء العــام.\nلمنــع مشــاركة عارضيــن غيــر مؤهليــن ،يجــب وضــع معاييــر تأهيــل موضوعيــة ومتناســبة مــع طبيعــة\n وأهميــة موضــوع الشــراء.\n\f 20\n .IIIالقسم الثالث :القيمة التقديرية\n السـؤال .24هل يمكن قبول أسعار أعلى من القيمة التقديرية؟\nالـــــــــجـــــــواب .تطبــق مذكــرة هيئــة الشــراء العــام رقــم /٤ه.ش.ع ٢٠٢٦/تاريــخ 2026/1/27المتعلقــة بالعــرض\n المرتفــع ســعره بشــكل غيــر اعتيــادي.\nوفعالــة عندمــا\n ّ السـؤال .25كيــف يمكــن للجهــة الشــارية وضــع القيمــة التقديريــة بطريقــة قانونيــة\nتكــون اســتطالعات األســعار مــن اإلدارات األخــرى غيــر متوفــرة أو غيــر عمليــة؟ وهــل\n ُيســمح بالتواصــل المباشــر مــع عــدد محــدود مــن المورديــن؟\nوفعالــة ،يجــب على الجهة الشــارية إجــراء تحليلالـــــــــجـــــــواب .الحتســاب ووضــع القيمــة التقديريــة بطريقــة قانونيــة ّ\nالمورديــن،\n ّ شــامل للســوق فــي مرحلــة التخطيــط للشــراء ،والــذي يشــمل التواصــل مــع عــدد كبيــر مــن\n علــى ســبيل المثــال مــن خــال اســتبيانات مكتوبــة توضــح الهــدف والغايــة بوضــوح وشــفافية.\n أما مصادر المعلومات األخرى التي يمكن ان تساعد في دراسة السوق فنذكر منها:\n .1المواقع االلكترونية."}, {"o": 24, "l": "المادة 24", "b": ".2المعارض أو الفعاليات التجارية حيث يمكن االطالع على األسعار والمنتجات المتوفرة في\n السوق.\n .3قاعدة بيانات األسعار المتوفرة لدى الجهة الشارية ،والتي تمّكّ نها من إجراء تقديرات\n دقيقة.\n توّفر قاعدة بيانات مركزية للحصول\n .4المنصة المركزية لدى هيئة الشراء العام ،والتي سوف ّ\n على مؤشرات دقيقة حول األسعار.\nالسـؤال .26مــا أهميــة تحديــد ســعر افتتــاح فــي المزايــدة العموميــة ،ومــا األســس التــي يجــب أن\n يرتكــز عليهــا هــذا التحديــد؟\n الـــــــــجـــــــواب .إن تحديــد ســعر افتتــاح للمزايــدة ُيعـ ّـد مــن العناصــر الجوهريــة ،إذ ّ\nيمثــل المنطلــق الــذي تُ ــزاد عليــه\nويعتبــر هــذا التحديــد أساســياً ،بحيــث يــؤدي عــدم\n المبالــغ ســواء بشــكل مقطــوع أو كنســبة مئويــةُ .\n التقيــد بــه إلــى إبطــال المزايــدة.\n ّ\nيجــب أن يســتند تحديــد ســعر االفتتــاح أو الســعر التخمينــي إلــى دراســة اقتصاديــة تحليليــة دقيقــة\nالمتوقعــة للقطــاع المنــوي تلزيمــه .إذ تفــرض القواعــد واألصــول العلميــة ،عنــد\n ّ لإليــرادات والنفقــات\nمفصــل مــن قبــل خبــراء ومتخصصيــن لقيــاس مردوديــة ّ اســتثمار أو بيــع أي منتــج ،القيــام بتقييــم\nالمنتــج وتوقعــات نمــوه ،وذلــك لضمــان تحديــد ســعر الطــرح بشــكل موضوعــي وســليم ،ومنــه تبــدأ\nتطبــق احــكام المــادة 13مــن قانــون الشــراء العــام المتعلقــة بالقيمــة التقديريــة لمشــروع\n المزايــدةّ .\n الشــراء.\n\f21\n ّ\n المتبعة عند الشراء بالفاتورة .IVالقسم الرابع :االجراءات\n السـؤال .27هل من الضروري تشكيل لجنة تلزيم عند اعتماد طريقة «الشراء بالفاتورة»؟\nعمــا بمذكــرة هيئــة الشــراء العــام رقــم /3ه.ش.ع2022/. ً الـــــــــجـــــــواب .عنــد اعتمــاد طريقــة الشــراء بالفاتــورة،\nوفقــا ألحــكام المادتيــن ()60"}, {"o": 25, "l": "المادة 24", "b": "ً تاريــخ ،2022/8/12ال ُيشــترط تشــكيل لجنــة تلزيــم .إذ إن هــذه الطريقــة،\nو( )61مــن قانــون الشــراء العــام ،ال تتطلّ ــب إعــداد دفتــر شــروط بــل تحديــد المواصفــات والكميــات\nلألشــغال واللــوازم والخدمــات المطلوبــة بشــكل دقيــق ،ويمكــن تنفيذهــا مــن خــال تكليــف موظــف\nواحــد أو أكثــر مــن وحــدة الشــراء لــدى الجهــة الشــارية القيــام باســتالم عــروض الشــراء بالفاتــورة\n واختيــار العــرض األدنــى ســعراً مــن بينهــا.\n السـؤال .28هل تخضع عمليات الشراء بطريقة الشراء بالفاتورة لموجب النشر؟\nالـــــــــجـــــــواب .إن العمليــات الجاريــة بطريقــة الشــراء بالفاتــورة ضمــن الســقف المالــي المحــدد لهــذه الطريقــة ال\nويســتعاض عــن ذلــك بإلــزام الجهــة الشــارية باإلعــان عــن\n تخضــع للنشــر الفــردي إلعــان اإلرســاءُ .\nعمــا بالمذكــرة رقــم 6تاريــخ 2022/8/19الصــادرة عــن\n ً جميــع عمليــات الشــراء بالفاتــورة ونشــرها\n وفقــا لمــا يلــي:\n ً هيئــة الشــراء العــام،\n • خالل شهر كانون الثاني من كل سنة :نشر اإلعالن عن عمليات الشراء التي جرت خالل\n النصف الثاني من السنة السابقة؛\n • خالل شهر تموز من كل سنة :نشر اإلعالن عن عمليات الشراء التي جرت خالل النصف\n األول من السنة نفسها.\nيتــم النشــر علــى الموقــع اإللكترونــي للجهــة الشــارية إن ُوجــد ،وعلــى المنصــة اإللكترونيــة المركزيــة\nـا بالمذكــرات ذات الصلــة لهيئــة الشــراء العــام ،باســتخدام النمــوذج الــذي وضعتــه الهيئــة ،وذلــك عمـ ً\n الصــادرة عنهــا.\n تطبق احكام المادتين 60و 11من قانون الشراء العام في هذه الحالة.\n ّ\n السـؤال .29هل تخضع عمليات الشراء بالفاتورة للموافقة المسبقة من هيئة الشراء العام؟"}, {"o": 26, "l": "المادة 24", "b": "الـــــــــجـــــــواب .إن عمليــات شــراء الخدمــات بطريقــة الشــراء بالفاتــورة ،المســموح بهــا ضمــن الســقف المالــي المحدد\nفــي المــادة 47مــن قانــون الشــراء العــام ،ال تخضــع لموافقــة هيئــة الشــراء العــام المســبقة علــى ان\nيتــم االلتــزام باإلجــراءات القانونيــة المنصــوص عليهــا فــي المادتيــن 60و 61مــن قانــون الشــراء العــام.\n السـؤال .30ما هي اإلجراءات الواجب اتباعها العتماد طريقة الشراء بالفاتورة؟\n الـــــــــجـــــــواب .تتم إجراءات الشراء بالفاتورة على النحو اآلتي:\nالمورديــن أو المقاوليــن ،علــى\n ّ تطلــب الجهــة الشــارية عــروض أســعار مــن أكبــر عــدد ممكــن عمليــاً مــن\nمــورد أو مقــاول ُيطلــب منــه تقديــم\n ّ ويبلَّ ــغ كل\n يقــل عددهــم عــن عارضيــن اثنيــن علــى األقــلُ .\n ّ ّأاّل\nعــرض أســعار بمــا إذا كان يجــب أن ُيــدرج فــي الســعر عناصــر أخــرى غيــر كلفــة موضــوع الشــراء نفســه،\nويســمح لــكل عــارض بتقديــم المطبقــةُ .\n ّ مثــل نفقــات النقــل ،التأميــن ،الرســوم الجمركيــة ،والضرائــب\n\f 22\nعــرض أســعار واحــد فقــط ،دون الســماح لــه بتعديلــه أو إجــراء مفاوضــات بشــأنه ،ويكــون العــرض\nيلبــي حاجــات الجهــة الشــارية كمــا هــو محــدد فــي طلــب\n الفائــز هــو العــرض األدنــى ســعراً الــذي ّ\n األســعار (المــادة 60مــن قانــون الشــراء العــام).\n\f23\n .Vالقسم الخامس :التعاقد بالتراضي\nالسـؤال .٣١مــا هــي الشــروط الواجــب توافرهــا العتمــاد الشــراء بواســطة اتفــاق رضائــي وفقـ ًـا\n لقانــون الشــراء العــام؟\n الـــــــــجـــــــواب .نصت"}, {"o": 27, "l": "المادة 46", "b": "المادة 46من قانون الشراء العام على ما يلي:\n «يجوز للجهة الشارية أن تقوم بالشراء بواسطة اتفاق رضائي ،في الظروف االستثنائية التالية:\n لموّرد أو\n ّ موّرد أو مقاول واحد ،أو عندما تكون .1عند عدم توفر موضوع الشراء إال عند ّ\n ويتعّذر اعتماد خيار أو بديل آخر.\n ّ مقاول حقوق ملكية فكرية فيما يخص موضوع الشراء،\n متوّقع ،ونتيجة ذلك ال\n ّ .2في حاالت الطوارئ واإلغاثة من جراء وقوع حدث كارثي وغير\n يكون استخدام أي طريقة شراء أخرى أسلوبًاً عمليًاً لمواجهة هذه الحاالت.\n توّفر الشروط التالية\n .3عند حاجة الجهة الشارية إلى التعاقد مع الملتزم األساسي عند ّ\n مجتمعة:\n أ .حصول الحاجة أثناء تنفيذ العقد؛\n ب.توفر حالة العجلة القصوى ووجوب التعاقد لمنع التأخير في التنفيذ؛ ُّ\n ج .وجوب توحيد المواصفات والتوافق أو التماثل مع السلع أو المعدات أو التكنولوجيا أو\n الخدمات أو األشغال الموجودة؛\n د .عدم تأدية اإلضافات إلى تبديل هدف العقد األساسي أو قلب اقتصادياته أو ضرب مبدأ\n المنافسة؛\n ه .تشكيل اللوازم أو األشغال أو الخدمات ملحقًاً للشراء األساسي وجزءًاً متممًاً له أو وجوب\n تنفيذ األشغال في مكان العمل؛\n توقع الحاجة اإلضافية أثناء التعاقد األساسي. و .عدم إمكانية ُّ\n .٤عند شراء لوازم أو خدمات أو تنفيذ أشغال تستوجب المحافظة على طابعها السري من\n بناًء على\n أجل مقتضيات األمن والدفاع الوطني ،وذلك وفقًاً لقرار ُُيتخذ في مجلس الوزراء ً\n اقتراح الوزير المختص الذي ُُيحدد الصفة السرية للشراء وأسباب التعاقد الرضائي.\n .٥عند التعاقد مع أشخاص القانون العام كالمؤسسات العامة والبلديات أو المنظمات\n الدولية.\n .٦عند التعاقد مع المستشفيات والمراكز الطبية والمختبرات».\nمــع التذكيــر بمــا ورد فــي المذكــرة رقــم 2الصــادرة عــن هيئــة الشــراء العــام بتاريــخ 2026/1/21حــول"}, {"o": 28, "l": "المادة 46", "b": "المــادة ٤٦مــن قانــون الشــراء العــام (شــروط االتفــاق الرضائــيَّ آليــة تطبيــق الفقــرة الرابعــة مــن\n َّ\nللــوازم واألشــغال والخدمــات ذات الطابــع الســري) .وبضــرورة النشــر عنــد زوال الظــروف المانعــة\nفــي مــا يتعلــق بالشــراء بالتراضــي المســند الــى المــادة - 46فقــرة -2مــن قانــون الشــراء العــام عمـ ًـا\n بمذكــرة هيئــة الشــراء العــام رقــم 2تاريــخ .2023/2/16\nالسـؤال .٣٢مــا هــي التزامــات الجهــة الشــارية فــي حالــة التعاقــد بالتراضــي وفقـ ًـا لقانــون الشــراء\n العام؟\nـا بأحــكام المــادة 62مــن قانــون الشــراء العــام ،عندمــا تقــوم الجهــة الشــارية بالشــراء مــن مصــدر الـــــــــجـــــــواب .عمـ ً\n واحــد وفقــاً للـــمادة 46مــن هــذا القانــون ،يتوجــب عليهــا اتبــاع اإلجــراءات التاليــة:\n\f 24\n .1تبِّلِ غ الجهة الشارية هيئة الشراء العام ّنّيتها بإجراء عقد بالتراضي وَتَ نشر إشعارًاً بالشراء\n الـمركزّية في هيئة الشراء العام وعلى\n ّ اإللكترونّية\n ّ بطريقة االتفاق الرضائي على الـمنصة\n موقعها االلكتروني إن ُُوجد ،وذلك قبل //10//عشرة أيام على األقل من تاريخ إبرام\n كحٍّد أدنى ،الـمعلومات التالية:\n ٍ وُيضَّمَ ن اإلشعار،\n العقدُ .\n أ .اسم الجهة الشارية وعنوانها؛\n طبيعَة وكمية السلعَ ب.ملّخصًاً ألهِّمِ األحكام والشروط الـمطلوبة في عقد الشراءََ ،يشمل ّ\n الـُمراد تنفيذها ،أو طبيعة\n الـُمراد توريدها ومكان تسليمها ،أو طبيعة وموقع األشغال ُ ُ\n تّم فيه توريد\n الخدمات والـموقع الذي ُُيراد تقديمها فيه ،وكذلك الوقت الـمطلوب أن ََي ّ\n السلع أو إنجاز األشغال أو تقديم الخدمات؛\n سيبرم بطريقة االتفاق الرضائي. أن العقد ُ جّ .\n الـُمشار إليها في الفقرتين\n طَّبَُق أحكام الفقرة األولى من هذه الـمادة في الحاالت ُ ُ .٢ال ُتُ"}, {"o": 29, "l": "المادة 46", "b": "الثانية والرابعة من الـمادة 46من هذا القانون.\n .3تقوم الجهة الشارية بطلب اقتراح أو عروض أسعار من عارض وحيد ،وُتُ جري مفاوضات\n مع هذا العارض ،ما لـم تكن تلك الـمفاوضات غير ممكنة عمليًاً في الظروف الـمحيطة\n الـمعنّية.\n ّ بعملية الشراء\n .4يمكن للجهة الشارية أن ُتُ سِنِ د التلزيم إلى العارض دون أن تَّتَ بع إجراءات تنافسية (المذكرة\n رقم 2الصادرة عن هيئة الشراء العام بتاريخ .)2026/1/21\nالسـؤال .٣٣هــل يخضــع العقــد الرضائــي بيــن مؤسســة عامــة وشــركات تحويــل األمــوال لتحصيــل\n فواتيــر ألحــكام قانــون الشــراء العــام؟\nالـــــــــجـــــــواب .يعتبــر العقــد الرضائــي ،بيــن مؤسســة عامــة وشــركات تحويــل األمــوال لتحصيــل فواتيــر خاضعــاً\nلقانــون الشــراء العــام .ويقتضــي توافــر أحــد الشــروط االســتثنائية للتعاقــد بالتراضــي المنصــوص عنهــا\nفــي المــادة 46مــن قانــون الشــراء العــام .إن الهــدف مــن هــذا التعاقــد هــو تســهيل عمليــة الجبايــة\nـاء علــى\n ـدال يدفعــه المشــترك مقابــل الخدمــة .بنـ ًوتخفيــف العــبء علــى المشــتركين ،وهــو يتضمــن بـ ً\nذلــك ،يدخــل هــذا التعاقــد ضمــن مفهــوم عمليــات الشــراء العــام كمــا هــو محــدد فــي قانــون الشــراء\nالعــام الــذي ينــص علــى أن الشــراء العــام يشــمل تعاقــدات لقــاء بــدل ُيدفــع للجهــات المتعاقــدة مــع\n اإلدارات العامــة.\n السـؤال .٣٤ما هي الشروط واإلجراءات المرتبطة بالتعاقد الرضائي في الحاالت االستثنائية ؟\nالـــــــــجـــــــواب .يتيــح قانــون الشــراء العــام ،التعاقــد المباشــر فــي حــاالت اســتثنائية حددتهــا المــادة 46وذلــك عندمــا\nيتعــذر تأميــن الحاجــات األساســية والملحــة بطريقــة شــراء أخــرى تنافســية .هــذا التعاقــد يجــب أن"}, {"o": 30, "l": "المادة 46", "b": "يكــون ضمــن حــدود تأميــن هــذه الحاجــات الضروريــة فقــط ،عمــا بالمذكــرة رقــم 8تاريــخ ،2024/9/30\n حــول تأميــن الحاجــات األساســية والملحــة فــي ظــل الظــروف اإلســتثنائية.\nـادة لمــدة ال تقــل عــن\n وفقــاً للمــادة 62مــن قانــون الشــراء العــامُ ،ينشــر اإلعــان المســبق للشــراء عـ ً\nطبــق هــذا النشــر المســبق وفــق الفقــرة 2مــن عشــرة أيــام .إال أنــه فــي الحــاالت االســتثنائية ،ال ُي ّ\nالمــادة ،62التــي تســتثني الحــاالت المنصــوص عليهــا فــي المــادة 46مــن عمليــة النشــر .اال انــه يجــب\nنشــر العقــود الناتجــة عــن هــذا التعاقــد بعــد زوال الظــروف االســتثنائية المانعــة ،وفقــاً للمذكــرة رقــم\n 2تاريــخ 2023/2/16الصــادرة عــن هيئــة الشــراء العــام.\n\f25\nالسـؤال .٣٥هــل يمكــن إعــداد اتفــاق بالتراضــي لتنفيــذ أعمــال اإلشــراف علــى مشــروع ترميــم\n ً\n وفقــا لقانــون الشــراء العــام؟\nالـــــــــجـــــــواب .ال يمكــن إعــداد اتفــاق بالتراضــي لتنفيــذ أعمــال اإلشــراف علــى مشــروع ترميــم وفقــاً لقانــون الشــراء\nالعــام .إذ تُ صنّ ــف األعمــال المتعلقــة باإلشــراف الفنــي علــى تنفيــذ المشــروع ،باإلضافــة إلــى الدراســة\nالهندســية والخدمــات االستشــارية األخــرى ،ضمــن فئــة «الخدمــات االستشــارية» كمــا هــو محــدد\n فــي المــادة -2فقــرة -11مــن قانــو ن الشــراء العــام.\nيجــب أن يخضــع شــراء هــذه الخدمــات إلجــراءات طلــب االقتراحــات المنصــوص عليهــا فــي المادتيــن\n 45و ٥٩مــن قانــون الشــراء العــام .ال يجــوز مخالفــة القاعــدة التنافســية المنصــوص عليهــا فــي المــادة\n 42مــن قانــون الشــراء العــام إال فــي الحــاالت االســتثنائية التــي نصــت عليهــا المــادة 46مــن القانــون.\nالمــورد"}, {"o": 31, "l": "المادة 46", "b": "ّ السـؤال .٣٦هــل يمكــن التعاقــد المباشــر لصيانــة برامــج تكنولوجيــا المعلومــات إذا كان\n هــو مالــك البرنامــج؟\nالـــــــــجـــــــواب .وفــق الفقــرة االولــى مــن المــادة 46مــن قانــون الشــراء العــام يمكــن التعاقــد اســتثنائياً بالتراضــي مــع\n ـورد الوحيــد او صاحــب الحــق الحصــري عنــد تعـ ّـذر اعتمــاد خيــار بديــل.\n المـ ّ\n\f 26\n .VIالقسم السادس :طلب عروض االسعار\nالتقيــد بهــا عنــد اعتمــاد الجهــات الشــارية طريقــة طلــب\n ّ السـؤال .37مــا هــي االجــراءات التــي يجــب\n عروض األســعار؟\n الـــــــــجـــــــواب .إجراءات اعتماد طريقة طلب عروض األسعار وفق قانون الشراء العام:\n ُيستعاض عن اإلعالن عن عملية الشراء العام على الموقع اإللكتروني للجهة الشارية أو ُ .1\n الموّردين المحددة\n ّ المنصة المركزية لدى هيئة الشراء العام ،بدعوة مباشرة للمقاولين أو\n أسماؤهم مسبقًاً في لوائح معتمدة ،باستخدام وسيلة سريعة ومضمونة ،وفق النموذج\n المنشور على الموقع الرسمي لهيئة الشراء العام( ."}, {"o": 32, "l": "المادة 58", "b": "المادة 58من قانون الشراء العام).\n .2يتم تسليم دفتر الشروط الخاص بالصفقة الى العارضين الذين ُُو ّّجهت إليهم دعوات من\n قبل اإلدارة.\n ُيلزم بنشر القرار المتعلق بقبول العرض الفائز (التلزيم المؤقت) والعقد بعد توقيعه علىُ .3\n المنصة اإللكترونية المركزية لدى هيئة الشراء العام ،وعلى الموقع اإللكتروني للجهة\n الشارية إن وجد ،وفق مذكرة هيئة الشراء العام رقمhttps://www.ppa.gov.lb/ar/ 2\n pages/details/36تاريخ .2023/2/16\nالمورديــن الذيــن\n ّ السـؤال .38مــا هــي اإلجــراءات التــي يجــب علــى الجهــة الشــارية اتخاذهــا لتحديــد\n ســتدعوهم للمشــاركة فــي المنافســة عنــد الشــراء بموجــب طلــب عروض األســعار؟\n الـــــــــجـــــــواب .وفقاً للفقرة الثانية من"}, {"o": 33, "l": "المادة 58", "b": "المادة 58من قانون الشراء العام ،يجب على الجهة الشارية:\n الموّردين أو المقاولين الذين ترغب في دعوتهم للمشاركة في المنافسة عند ّ • تحديد\n استخدام طريقة طلب عروض األسعار بحسب"}, {"o": 34, "l": "المادة 44", "b": "المادة 44من القانون.\n • توجيه الدعوة لهم مباشرة وبوسيلة سريعة ومضمونة.\n • إعداد لوائح بالعارضين المدعوين وإدراج هذه اللوائح في سجل إجراءات الشراء المنصوص\n عليه في"}, {"o": 35, "l": "المادة 9", "b": "المادة 9من القانون.\n • تحديث اللوائح بشكل دوري وفقاً لإلرشادات الصادرة عن هيئة الشراء العام.\nوقــد أصــدرت هيئــة الشــراء العــام المذكــرة رقــم 5تاريــخ https://www.ppa.gov.lb/ar/ 2024/8/7\n pages/details/75حــول توضيــح إجــراءات الدعــوة إلــى طلــب عــروض األســعار.\n\f27\n .VIIالقسم السابع :خدمات استشارية\nالسـؤال .39هــل يجــوز للشــخص أو الجهــة التــي شــاركت فــي تنفيــذ خدمــات استشــارية (كإعــداد\n ً\nالحقــا فــي تنفيــذ الصفقــة أو دراســة أو مواصفــات أو دفتــر شــروط) أن تشــارك\n تلزيمهــا؟\nالـــــــــجـــــــواب .كقاعــدة عامــة ،ال يجــوز للشــخص أو الجهــة التــي شــاركت ،بصــورة مباشــرة أو غيــر مباشــرة ،فــي\nتقديــم خدمــات استشــارية لتحضيــر الدراســة أو المواصفــات أو مســتندات الشــراء ،أن تشــارك الحقــاً\n فــي إجــراءات تلزيــم أو تنفيــذ الصفقــة نفســها.\nوفقــا للمــادة ( 2فقــرة )30مــن قانــون\n ً ويعــود ذلــك إلــى أن هــذا الوضــع ُيشــكّ ل حالــة تضــارب مصالــح\n الشــراء العــام ،لمــا ينطــوي عليــه مــن مســاس بحيــاد ونزاهــة إجــراءات الشــراء.\nويعتبــر تضــارب المصالــح قائمــاً أيضــاً إذا كان العــارض قــد عمــل خــال الســنتين الســابقتين لــدى جهــة ُ\nقامــت بهــذه الخدمــات االستشــارية ،متــى كان مــن شــأن ذلــك التأثيــر علــى المنافســة أو إعطــاء\n أفضليــة غيــر مبـ ّـررة.\nاســتثناء ،يمكــن الجمــع بيــن مرحلتــي االستشــارة والتنفيــذ فقــط فــي حالــة المشــروع المتكامــل ً\nجزئيــا أو كليــاً ،\n ً ( ،)Turnkey Projectحيــث يتولــى الملتــزم تنفيــذ مراحــل متعــددة مــن المشــروع\nشــرط أن تــرى الجهــة الشــارية مصلحــة عامــة واضحــة فــي اعتمــاد هــذا األســلوب ،وأن يتــم اإلفصــاح"}, {"o": 36, "l": "المادة 9", "b": "المســبق والصريــح عــن ذلــك فــي ملــف الشــراء مــع بيــان األســباب التبريريــة.\n\f 28\n .VIIIالقسم الثامن :االتفاق اإلطاري\n السـؤال .40ما هي الشروط التي يجب أن تتوافر للجوء الى االتفاق اإلطاري؟\nالـــــــــجـــــــواب .تحــدد الفقــرة األولــى مــن المــادة 48مــن قانــون الشــراء العــام امكانيــة لجــوء الجهــة الشــارية إلــى\n اســتخدام االتفــاق اإلطــاري فــي إحــدى الحالتيــن التاليتيــن:\n متكرر وغير مؤكَّ دة التاريخ؛\n ّ حتملة الوقوع على نحو\n .1عندما تكون الحاجة ُم َ\n معينة\n .2عندما تنشأ الحاجة إلى موضوع الشراء ،بحكم طبيعته ،على نحو ُمستعجل أثناء فترة َّ\n من الزمن.\n\f29\n .IXالقسم التاسع :عقود الصيانة وقطع الغيار\n السـؤال .41هل من الممكن عقد اتفاق اطاري لصفقات الصيانة؟\nالـــــــــجـــــــواب .ان صفقــات الصيانــة علــى اختالفهــا تعــد بمثابــة النمــوذج االمثــل لعقدهــا بموجــب إتفاقــات إطاريــة،\nكونهــا تســتوفي شــروط اســتخدام هــذه األســلوب للتعاقــد والمحــددة فــي البنــد األول مــن المــادة\n /48/مــن قانــون الشــراء العــام وفقــاً لآلتــي:\n«يمكــن للجهــة الشــارية أن تَ لجــأ إلــى إجــراءات اتفــاق إطــاري ،وفقــاً ألحــكام البنــد الثامــن مــن هــذا\n الفصــل ،فــي إحــدى الحالتيــن التاليتيــن:\n متكرر وغير مؤكَّ دة التاريخ.\n ّ حتملة الوقوع على نحو\n .1عندما تكون الحاجة ُم َ\n معينة\n .2عندما تنشأ الحاجة إلى موضوع الشراء ،بحكم طبيعته ،على نحو ُمستعجل أثناء فترة َّ\n من الزمن».\nالتقيد باإلجــراءات واألصولّ فــي حــال قــررت الجهــة الشــارية اتبــاع هــذا االســلوب فــي التعاقــد ،عليهــا\nالمنصــوص عليهــا فــي البنــد الثامــن مــن الفصــل الثـالـــث مــن قانــون الشــراء العــام ،منهــا مــا فرضتــه"}, {"o": 37, "l": "المادة 9", "b": "المــادة ،/63/مــن موجــب إرســاء اإلتفــاق اإلطــاري ،إمــا بواســطة إجــراءات المناقصــة العموميــة\nوإمــا بواســطة المناقصــة علــى مرحلتيــن وإمــا بواســطة طلــب عــروض األســعار ،وبمــا ال يتعــارض مــع\nاألحــكام الخاصــة باالتفــاق اإلطــاري .يضــاف الــى اإلجــراءات المنــوه عنهــا ،مــا أوجبتــه المــادة /57/\nمــن قانــون المحاســبة العموميــة ،مــن ضــرورة توفــر االعتمــاد فــي موازنــة الجهــة الشــارية المعنيــة\n لصحــة عقــد اتفــاق إطــاري.\nالسـؤال .42هــل يمكــن طــرح مناقصــة واحــدة تشــمل أعمــال الصيانــة وقطــع الغيــار معـ ًـا ،علــى\n أســاس المبلــغ اإلجمالــي؟\nالـــــــــجـــــــواب .مــن الناحيــة القانونيــة ،ال يوجــد مــا يمنــع طــرح مناقصــة واحــدة تشــمل أعمــال الصيانــة وقطــع الغيــار\nمعــاً .إال أنــه مــن الناحيــة العمليــة ،يجــب اختيــار الحــل األكثــر مالءمــة مــع مراعــاة تحقيــق أفضــل قيمــة\n مقابــل إنفــاق المــال العــام.\nوفــي حــال الجمــع بيــن الصيانــة وقطــع الغيــار ضمــن عقــد واحــد ،يمكــن تقديــر االحتيــاج الفعلــي مــن\nـاء عليــه ،يتــم\n خــال دراســة تكــرار عمليــات الصيانــة الســابقة ،وذلــك لتحديــد نــوع العقــد األنســب .وبنـ ً\n اتخــاذ القــرار فــي كل حالــة علــى حــدة.\nفضــل التعاقــد مــع نفــس المــورد لتنفيــذ نفــس نــوع األعمــال متــى كان ذلــك يحقــق\n وبوجــه عــامُ ،ي َّ\n الكفــاءة والجــودة المطلوبــة.\nالسـؤال .43مــا هــي أفضــل طريقــة للتعاقــد علــى خدمــات الصيانــة فــي حــال كانــت احتياجــات\nالصيانــة الوقائيــة محــددة بوضــوح ،فــي حيــن يصعــب التنبــؤ باحتياجــات الصيانــة\n التصحيحيــة وقطــع الغيــار؟"}, {"o": 38, "l": "المادة 9", "b": "الـــــــــجـــــــواب .فيمــا يتعلــق بالصيانــة الوقائيــة ،يمكــن اللجــوء إلــى عقــد عــادي ،وذلــك عندمــا تكــون األعمــال\n\f 30\nمحــددة ومعلومــة مســبقاً ،كمــا فــي حالــة صيانــة المصاعــد التــي تتطلــب تنفيــذ أعمــال صيانــة دوريــة\n منتظمــة (علــى ســبيل المثــال ،بشــكل شــهري).\nفيعـ ّـد االتفــاق\n أمــا بالنســبة ألعمــال الصيانــة التصحيحيــة التــي يصعــب التنبــؤ بتوقيتهــا أو حجمهــاُ ،\n اإلطــاري الخيــار األنســب.\nـورد واحــد أو أكثــر ،وفقــاً لطبيعــة\n وفيمــا يخــص قطــع الغيــار ،يمكــن أيضــاً إبــرام اتفــاق إطــاري مــع مـ ّ\n االحتيــاج وبمــا يضمــن المرونــة وســرعة توفيــر القطــع عنــد الحاجــة.\nالسـؤال .44هــل يمكــن للجهــة الشــارية أن تشــترط علــى العارضيــن الحصــول علــى شــهادة مــن\nالشــركة المصنِّ عــة األصليــة ( )OEMلبعــض المشــتريات ،مثــل صيانــة المولــدات وقطــع\n الغيــار؟\nالـــــــــجـــــــواب .يعتمــد ذلــك علــى طبيعــة كل حالــة علــى حــدة .كقاعــدة عامــة ،ال يجــوز للجهــة الشــارية إدراج شــروط\nمــن شــأنها تقييــد المنافســة بيــن العارضيــن المؤهليــن لتنفيــذ موضــوع الشــراء .إذ يتوجــب توفيــر\nفــرص متســاوية لجميــع مقدمــي الطلبــات المحتمليــن ،كمــا أن إدراج شــروط تــؤدي إلــى حصــر\nالمنافســة ضمــن فئــة محــددة مــن العارضيــن ال ينســجم مــع مبــادئ وأحــكام قانــون الشــراء العــام.\nوتُ عـ ّـد المناقصــة العموميــة القاعــدة العامــة فــي الشــراء ،وبحكــم طبيعتهــا ،يجــب أن تكــون مفتوحــة\nيلبــي\n أمــام جميــع مقدمــي الطلبــات المؤهليــن .وفــي نهايــة المطــافُ ،يمنــح العقــد للعــارض الــذي ّ\n عرضــه حاجــات الجهــة الشــارية وفــق الشــروط والمواصفــات المحــددة."}, {"o": 39, "l": "المادة 9", "b": "ومــع ذلــك ،يمكــن للجهــة الشــارية تضميــن متطلبــات محــددة ضمــن قســم المواصفــات الفنيــة ،دون\nتفضــل\n اإلشــارة إلــى الشــركة المصنِّ عــة األصليــة .فعلــى ســبيل المثــال ،إذا كانــت الجهــة الشــارية ّ\nاســتخدام قطــع غيــار ذات عمــر تشــغيلي ال يقــل عــن خمــس ســنوات ،يمكــن النــص في دفتر الشــروط\nعلــى أن القطــع المطلوبــة يجــب أن تحقــق هــذا العمــر التشــغيلي ،مــع اعتمــاد صيغــة «قطــع أصليــة\nأو مــا يعادلهــا» ،وإدراج مؤشــرات األداء والمواصفــات الفنيــة المعتمــدة للقطــع األصليــة ضمــن\nالمواصفــات المطلوبــة .ويتيــح ذلــك المجــال أمــام عــروض لقطــع غيــر أصليــة محتملــة ذات كلفــة\n أقــل ،شــرط أن تكــون مطابقــة للمواصفــات المطلوبــة.\nكمــا قــد تســتدعي شــروط المناقصــة إدراج مؤهــات محــددة للعارضيــن ،كاشــتراط أن يكــون العــارض\nموزّ عــاً معتمــداً لموضــوع الشــراء ،وذلــك فــي الحــاالت التــي يمكــن فيهــا تبريــر هــذا الشــرط موضوعياً ،\nوعندمــا يكــون ضروريــاً نظــراً لوجــود مخاطــر فعليــة ،بحيــث يقتصــر تقديــم الخدمــة المطلوبــة علــى\nالموزّ عيــن المعتمديــن فقــط ،ويكــون التعاقــد مــع غيــر المعتمديــن محفوفــاً بالمخاطــر .إضافـ ًـة إلــى\n ذلــك ،فقــد حـ ّـدد القانــون حــاالت التعاقــد بالتراضــي متــى توافــرت شــروطه القانونيــة.\n\f31\n .Xالقسم العاشر :اجراءات التلزيم /ارساء العقود\n السـؤال .45ماذا تشمل إجراءات فتح وتقييم العروض من قبل لجان التلزيم؟\n الـــــــــجـــــــواب .وفقاً لقانون الشراء العام ،تشمل إجراءات فتح وتقييم العروض في لجان التلزيم ما يلي:\n .1فتح العروضُ :تُ فتح العروض في جلسة علنية بعد انتهاء مهلة تقديمها ،وفقًاً ألحكام\n وّقع من رئيس وأعضاء اللجنة ،مع تسجيل حّرر محضر للجلسة ُُي ّوُي ّ"}, {"o": 40, "l": "المادة 54", "b": "المادة 54من القانونُ .\n حضور العارضين أو ممثليهم.\n وّثق كافة وقائع الجلسة في سجل إجراءات الشراء ،وفقًاً للمادة 9من .2تسجيل الوقائعُ :تُ ّ\n القانون ،لضمان الشفافية والمتابعة.\n .3تقييم العروض :يتم تقييم العروض المالية بشكل منفصل عن العروض اإلدارية والفنية،\n بعد دراسة استيفاء كل عرض للشروط والمتطلبات المنصوص عليها ،وفقًاً للمادة 55من\n القانون.\n .4طلب التوضيحات :يحق للجهة الشارية طلب توضيحات أو مستندات إضافية من العارضين\n عند الحاجة ،خطيًاً ،مع مراعاة الشفافية وعدم إجراء أي تغييرات جوهرية في العروض\n المقدمة.\n .5الرقابة :على الرغم من استقاللية لجان التلزيم ،فإن إجراءاتها تخضع لرقابة هيئة الشراء\n العام والجهات الرقابية القضائية واالدارية لضمان حسن االلتزام بالقانون.\n .6إبالغ العارضين بالرفض :تلتزم الجهة الشارية بإبالغ العارضين الذين ُُرفضت عروضهم كتابيًاً ،\n مع تقديم أسباب مفصلة ومعّلّ لة للرفض.\nتهــدف هــذه اإلجــراءات إلــى ضمــان الشــفافية والمســاواة بيــن العارضيــن وااللتــزام الصــارم بأحــكام\n قانــون الشــراء العــام رقــم 2021/244\nالسـؤال .46هــل مــن مانــع قانونــي مــن أن يكــون رئيــس وحــدة الشــراء أو أحــد اعضائهــا ممــن\n شــاركوا فــي إعــداد دفاتــر الشــروط اإلداريــة والفنيــة المتعلقــة بالصفقــات عضـ ً\nـوا مــن\n أعضــاء لجنــة التلزيــم؟\nالـــــــــجـــــــواب .ال مانــع قانونــي مــن أن يكــون رئيــس وحــدة الشــراء أو أحــد اعضائهــا ممــن شــاركوا فــي إعــداد دفاتــر\nالشــروط اإلداريــة والفنيــة المتعلقــة بالصفقــات عضــواً مــن أعضــاء لجنــة التلزيــم بشــرط أن ال يكــون\nفــي حالــة تضــارب مصالــح مــع المشــاركين فــي إجــراءات الشــراء ،وأن تتصــرف اللجنــة بشــكل مســتقل\n عــن الجهــة الشــارية فــي كل أعمالهــا وقراراتهــا."}, {"o": 41, "l": "المادة 54", "b": "للمزيــد مــن التفصيــل حــول حــاالت تضــارب المصالــح ،يمكــن الرجــوع الــى البنــد 30مــن المــادة 2مــن\nقانــون الشــراء العــام وقــرار هيئــة الشــراء العــام رقــم 79تاريــخ 2025/9/23المتضمــن ُشــرعة قواعــد\n بعمليــات الشــراء العــام.\n ّ المهنيــة والمواطنــة الصالحــة الخاصــة\n ّ الســلوك واألخــاق\nالسـؤال .47هــل يمكــن للجهــة الشــارية تلزيــم العــارض الثالــث أو الرابــع فــي حــال تمنّ ــع الملتــزم\n المؤقــت والعــارض الــذي يليــه مــن توقيــع العقــد؟\nالـــــــــجـــــــواب .ان الفقــرة 8مــن المــادة ٢٤مــن قانــون الشــراء العــام تتيــح للجهــة الشــارية التعاقــد مــع العــارض الفائــز\n\f 32\nالــذي يلــي عرضــه عــرض الملتــزم المؤقــت فــي حــال تمنّ ــع الملتــزم المؤقــت عــن توقيــع العقــد ،شــرط\nأن تكــون صالحيــة عرضــه مــا تــزال ســارية المفعــول ،وذلــك دون الزامــه بتوقيــع العقــد أو مصــادرة\n ضمــان عرضــه.\nإن هــذه االمكانيــة معطــاة للجهــة الشــارية مــرة واحــدة بمقتضــى النــص ،وال يجــوز اللجــوء اليهــا مــن\nحيــث المبــدأ ألكثــر مــن مــرة .فــإذا امتنــع العــارض الــذي يلــي عرضــه العــرض الفائــز عــن توقيــع العقــد،\n فيجــب فــي هــذه الحالــة كقاعــدة إلغــاء إجــراءات المناقصــة وإعــادة اجرائهــا مــن جديــد.\n السـؤال .48ما هي المتطلبات األساسية لتشكيل لجان التلزيم واالستالم؟\nالتقيــد\n ّ الـــــــــجـــــــواب .فــي الحــاالت التــي يتــم فيهــا اعتمــاد طــرق شــراء تســتدعي تشــكيل لجــان تلزيــم ،يجــب\n بالمتطلبــات القانونيــة التاليــة:\n • تكوين لجنة التلزيم ("}, {"o": 42, "l": "المادة ١٠٠", "b": "المادة ١٠٠من قانون الشراء العام) :يجب أن تتألف لجنة التلزيم من\n رئيس وعضوين أصيلين على األقل ،إضافة إلى رئيس وعضوين رديفين يحّلّ ون محل األعضاء\n األصيلين عند غيابهم ،على أن يكون عدد األعضاء دائما مفرد ،وأال يكون الرئيس واألعضاء\n في تضارب مصالح مع المشاركين في اجراءات الشراء ،وأن تتصرف اللجنة بشكل مستقل\n عن الجهة الشارية.\n يتّم تأليف هذه اللجان من أهل الخبرة واالختصاص وفقا ألسس تضعها هيئة الشراء العام، • ّ\n مع األولوية لألشخاص المدربين على الشراء العام.\n • الالئحة السنوية وتصاريح النزاهة :يتوجب إعداد الالئحة السنوية ألعضاء اللجان وتقديم\n تصاريح النزاهة ،وذلك وفق النماذج الصادرة عن هيئة الشراء العام.\n • االلتزام بالقرار رقم 9تاريخ :2023/10/11يجب أن يتم تشكيل لجان التلزيم وفق األسس\nينّظم قواعد واسس تأليف لجان التلزيم واالستالم. والضوابط المحددة في هذا القرار ،الذي ّ\nطبــق المبــادئ المنصــوص عليهــا فــي المــادة ( )101مــن قانــون\n أمــا بالنســبة إلــى لجــان االســتالم ،فتُ َّ\n الشــراء العــام ،وكذلــك أحــكام القــرار رقــم 9تاريــخ .2023/10/11\nفتطبــق القواعــد الــواردة فــي دليلــي عمــل لجــان التلزيــم\n ّ امــا بالنســبة لعمــل لجــان التلزيــم واالســتالم\n والمتوفــرة علــى الموقــع االلكترونــي للهيئة.\n ّ واالســتالم الصــادرة عــن هيئــة الشــراء العــام\n السـؤال .49هــل يمكــن للجهــة الشــارية اســتبدال أحــد أعضــاء لجنــة التلزيــم فــي يــوم فـ ّ\nـض العروض\n ً\n غائبا ؟ إذا كان العضــو األصيــل\nالـــــــــجـــــــواب .عنــد غيــاب رئيــس او أحــد اعضــاء لجنــة التلزيــم ألي ســبب كان يســتدعى الرئيــس او العضــو الرديــف\n اوال.\n ـا بالمــادة 100مــن قانــون الشــراء العــام البنــد ً\n للحلــول محلــه فــي ممارســة مهامــه عمـ ً"}, {"o": 43, "l": "المادة ١٠٠", "b": "السـؤال .50كيــف يتــم تشــكيل لجــان التلزيــم ولجــان االســتالم فــي البلديــات التــي تعانــي مــن\nنقــص فــي الموظفيــن ،وفقـ ًـا لقانــون الشــراء العــام وقــرارات هيئــة الشــراء العــام؟\nحــدد قانــون الشــراء العــام إجــراءات تشــكيل لجــان التلزيــم ولجــان االســتالم ،وقــد فصلتهــا هيئــة\n ّ الـــــــــجـــــــواب.\nالشــراء العــام بموجــب قرارهــا رقــم 9تاريــخ ،2023/10/11الــذي أجــاز اختيــار رئيــس وأعضــاء اللجــان\n (األصيلــة والرديفــة) مــن بيــن موظفــي ومتعاقــدي الجهــة الشــارية.\n\f33\nنصــت المــادة 100مــن قانــون الشــراء العــام علــى انــه « تتألــف لجنــة التلزيــم لــدى الجهــة الشــارية\nيكمــان اللجنــة عنــد غيــاب\n رديفيــن َّ وعضويــن\n َ وعضويــن أصيلَ يــن علــى األقــل ومــن رئيــس\n َ مــن رئيــس\nالرئيــس أو أحــد األعضــاء ،علــى أن يكــون عــدد أعضائهــا دائمــاً مفــرداً .يجــب ّأاّل يكــون الرئيــس أو\nاألعضــاء فــي حالــة تضــارب مصالــح مــع الـــمشاركين فــي إجــراءات الشــراء ،وأن تتصـ ّـرف اللجنــة بشــكل\n كل أعمالهــا وقراراتهــا.\n ـتقل عــن الجهــة الشــارية فــي ّ\n مسـ ّ\nبتــم تأليــف لجــان التلزيــم لــدى الجهــات الشــارية مــن أهــل الخبــرة واالختصــاص وفقــاً ألســس تضعهــا\nهيئــة الشــراء العــام علــى أن تكــون األولويــة فــي تشــكيل هــذه اللجــان لألشــخاص الـــمدربين علــى\n الشــراء العــام».\nامــا المــادة 101مــن قانــون الشــراء العــام فقــد نصــت علــى انــه «يتــم تأليــف لجــان االســتالم لــدى\nالجهــات الشــارية مــن أهــل الخبــرة واالختصــاص وفقــاً ألســس تضعهــا هيئــة الشــراء العــام علــى أن\n تكــون األولويــة فــي تشــكيل هــذه اللجــان لألشــخاص الـــمدربين علــى الشــراء العــام."}, {"o": 44, "l": "المادة ١٠٠", "b": "تعيــن لجنــة االســتالم بقــرار مــن المديــر العــام فــي االدارات والمؤسســات العامــة وبقرار من الســلطة ّ\nالتقريريــة فــي البلديــات وغيرهــا مــن الهيئــات ،وهــي تختلــف فــي قوامهــا وأعضائهــا عــن لجنــة التلزيــم\nوال تضــم االشــخاص الذيــن اشــتركوا فــي االشــراف علــى التنفيــذ او الذيــن درســوا الســوق او وضعــوا\n القيمــة التقديريــة للشــراء .تتألــف كل لجنــة مــن رئيــس وعضويــن علــى االقــل».\nكاف مــن الموظفيــن أو المتعاقديــن ،يمكــن اختيــار األعضــاء مــن بيــن\n وفــي حــال عــدم توافــر عــدد ٍ\n ســائر العامليــن المشــمولين بأحــكام المــادة 111مــن قانــون الموازنــة العامــة لعــام .2022\nفيســمح باالســتعانة تقــدمُ ،\n ّ فــي حــال عــدم توافــر موظفيــن أو متعاقديــن أو عامليــن وفقــاً لمــا\nبأعضــاء مــن المجلــس البلــدي لتشــكيل لجــان التلزيــم ولجــان االســتالم ،علــى أن ُيســتثنى رئيــس\nتلقــوا تدريبــات فــي مجــال الشــراء\n البلديــة مــن هــذه اللجــان ،وأن تُ عطــى األولويــة لألعضــاء الذيــن ّ\n العــام ،فــي حــال توافرهــم.\n السـؤال .51هل يمكن فتح العرض الوحيد في ظل قانون الشراء العام؟\nالـــــــــجـــــــواب .يمكــن فتــح العــرض الوحيــد فــي ظــل قانــون الشــراء العــام إذا كانــت الجهــة الشــارية قــد وضعــت\nقيمــة تقديريــة لمشــروع الشــراء وكان موضــوع الشــراء يشــكل حاجــة أساســية وملحــة بحيــث يتــم\nالتعاقــد مــع مقــدم العــرض الوحيــد المقبــول عنــد توفــر الشــروط القانونيــة المحــددة فــي الفقــرة ()4\n مــن المــادة ( )25مــن قانــون الشــراء العــام.\n تطبق في هذا الشأن االحكام الواردة في مذكرة هيئة الشراء العام رقم 10تاريخ .2022/10/24\nمقــدم العــرض الوحيــد"}, {"o": 45, "l": "المادة ١٠٠", "b": "ّ السـؤال .52مــا هــي الشــروط الواجــب توافرهــا للســماح بالتعاقــد مــع\n المقبــول وفــق قانــون الشــراء العــام؟\nالـــــــــجـــــــواب .يحــق للجهــة الشــارية التعاقــد مــع مقـ ّـدم العــرض الوحيــد المقبــول ،شــرط توافــر الشــروط التاليــة\n مجتمعــة:\n مطّبقة بالكامل ،وأاّلا يكون العرض الوحيد ناتجًاً\n ّ • أن تكون مبادئ وأحكام قانون الشراء العام\n تضّمنها دفتر الشروط الخاص بعملية الشراء. ّ عن شروط حصرية أو تقييدية\n\f 34\n وملّحة ،وأن يكون السعر المعروض منسجمًاً مع ّ • أن تكون الحاجة المراد تلبيتها أساسية\n دراسة القيمة التقديرية المعتمدة.\n نّصًاً صريحًاً يفيد بقبول\n المؤّقت) ّ\n ّ يتضّمن قرار الجهة الشارية بقبول العرض الفائز (التلزيم\n ّ • أن\n مقّدمه.\n ّ وبنّيتها التعاقد مع\n العرض الوحيد المقَّدَ م ّ\nالتقيــد باإلجــراءات الــواردة فــي المذكــرة رقــم ٢تاريــخ 2025/3/24الصــادرة عــن هيئــة ّ كمــا يجــب\nوالموجهــة إلــى جميــع الجهــات الخاضعــة ألحــكام قانــون الشــراء العــام ،والتــي توضــحّ الشــراء العــام\nإجــراءات التعاقــد مــع مقـ ّـدم العــرض الوحيــد تطبيقــاً ألحــكام المــادة ( )25مــن قانــون الشــراء العــام،\nســواء نتجــت حالــة العــرض الوحيــد عــن تقديــم عــرض واحــد منــذ البدايــة ،أو عــن بقــاء عــرض واحــد بعــد\n فتــح العــروض وتقييمهــا.\n\f35\n .XIالقسم الحادي عشر :استبعاد العارض/نكول الملتزم\n ً\n ناكال؟ السـؤال .53ما هي الحاالت التي تؤدي إلى اعتبار الملتزم\nالـــــــــجـــــــواب .حــددت المــادة 33مــن قانــون الشــراء العــام أســباب انتهــاء العقــد ومــن ضمنهــا حالــة النكــول ،حيــث\n نصــت علــى التالــي:\n ّ\n ناكًال إذا خاَلَ ف شروط تنفيذ العقد أو أحكام دفتر الشروط ،وبعد إنذاره ً الـملتِزم\n ِ «ُيعتبرُ .1"}, {"o": 46, "l": "المادة ١٠٠", "b": "بكاّفة موجباته من قبل سلطة التعاقد ،وذلك ضمن مهلة تتراوح ّ رسميًاً بوجوب التقُّيُ د\n كحٍّد أقصى ،وانقضاء الـمهلة هذه دون أن ٍ كحٍّد أدنى وخمسة عشر يومًاًٍ بين خمسة أيام\n الـُملتزم بما ُُطلب إليه.ََيقوم ُ\n بناًء على موافقة\n ناكًال إاّلا بموجب قرار معَّلَ ل ََيصدر عن سلطة التعاقد ً ً الـُملتزم\n .2ال يجوز اعتبار ُ\n هيئة الشراء العام.\n ناكًالُُ ،يفسخ العقد حكمًاً دون الحاجة إلى أِّيِ إنذار ،وُتُ طَّبَ ق اإلجراءات\n ً .3إذا اعُتُ بر الـملتزم\n الـمنصوص عليها في الفقرة األولى من البند الرابع من هذه الـمادة».\n ً\n ناكال؟ السـؤال .54ما هي االثار المترتبة على اعتبار الملتزم\nالـــــــــجـــــــواب .فــي حــال تطبيــق إحــدى حــاالت النكــول تَ عمــد ســلطة التعاقــد إلــى إعــادة التلزيــم وفقــاً لألصــول\nنفذهــا بنفســها إذا كان لديهــا الـــمؤهالت والقــدرات الـــمنصوص عليهــا فــي قانــون الشــراء العــام أو تُ ّ\nأي نــوع مــن أنــواع التعاقــد .فــإذا َأسـ َـفر التلزيــم الجديــد أو التنفيــذالكافيــة لذلــك دون اللجــوء إلــى ّ\nعــن ِوفـ ٍـر فــي األكالف ،عــاد الوفــر إلــى الخزينــة ،وإذا أســفر عــن زيــادة فــي األكالف ،رجعــت ســلطة\nـادر ضمــان حســن التنفيــذ مؤقتــاً إلــى التعاقــد علــى الـــملتزم النــاكل بالزيــادة .فــي جميــع األحــوال يصـ َ\n حيــن تصفيــة التلزيــم.\n كما يترتّ ب على قرار النكول النتائج القانونية التالية ،ال سيما:\n •تطبيق الجزاءات المالية ومصادرة الضمانات عند االقتضاء؛\n •إقصاء الملتزم من المشاركة في الشراء العام وفق المادة ،40وذلك:\n -لمدة سنة واحدة عند المرة األولى؛\n -لمدة سنتين عند المرة الثانية؛\n بدءا من تاريخ نشر قرار اإلقصاء.\n -لمدة خمس سنوات عند المرة الثالثة أو أكثرً ،\nيتحقــق مــن جديــة األســباب وصحــة"}, {"o": 47, "l": "المادة ١٠٠", "b": "ّ تخضــع قــرارات النكــول واإلقصــاء لرقابــة القضــاء اإلداري ،الــذي\n اإلجــراءات المتّ بعــة.\n السـؤال .55كيف يمكن للعارض استعادة أهليته بعد استبعاده؟\n الـــــــــجـــــــواب .يمكن للعارض أن يستعيد أهليته إذا زال سبب االستبعاد أو إذا حصل على إعادة تأهيل قانونية.\nفــي هــذه الحالــة ،يتوجــب علــى هيئــة الشــراء العــام تحديــث ســجل االســتبعاد وإزالــة اســم العــارض\n ـاء علــى طلــب مقـ ّـدم منــه.\n مــن قائمــة المســتبعدين ،إمــا بشــكل تلقائــي أو بنـ ً\n\f 36\nاألخــوة) بيــن مالكــي أو مديــري شــركات\n ّ ّ\n شــكل القرابــة العائليــة (كعالقــة السـؤال .56هــل تُ\nـببا قانونيـ ًـا الســتبعاد هــذه الشــركات مــن إجــراءات الشــراء\n مشــاركة فــي المناقصــة سـ ً\n العــام؟\nالـــــــــجـــــــواب .كقاعــدة عامــة ،ال تُ شــكّ ل القرابــة العائليــة بحــد ذاتهــا ســبباً قانونياً الســتبعاد العارضين من المشــاركة\nعــد قانونــاً كيانــات مســتقلة ومنفصلــة عــن\n فــي المناقصــة .فالشــركات المملوكــة مــن أشــقاء تُ ّ\nبعضهــا البعــض ،وتبقــى خاضعــة لمبــدأي االســتقاللية والمنافســة المنصــوص عليهمــا فــي قانــون\n الشــراء العــام ،وال ســيما المــادة ( 2فقــرة .)30\nوتبقــى العبــرة فــي مــدى اســتقاللية العــروض وليــس في وجود القرابة بحد ذاته .يقصد باســتقاللية\nالعــروض أن تكــون كل شــركة قــد أعـ ّـدت عرضهــا الفنــي والمالــي بصــورة منفصلــة ومســتقلة ،ومــن\n دون أي تنســيق أو تبــادل للمعلومــات مــع شــركات أخــرى مشــاركة فــي اإلجــراء نفســه.\nتبيــن للجنــة التلزيــم ،اســتناداً إلــى الوقائــع والمعطيــات،\n وعليــه ،ال تُ عـ ّـد القرابــة مانعــاً قانونيــاً إال إذا ّ"}, {"o": 48, "l": "المادة ١٠٠", "b": "وجــود تنســيق أو تواطــؤ بيــن العارضيــن مــن شــأنه اإلخــال بمبــدأ المنافســة الفعليــة أو المســاس\n باســتقاللية العــروض.\nيتعيــن علــى لجنــة التلزيــم اتخــاذ تدابيــر تضمــن الشــفافية والمنافســة الســليمة،\n ّ وللتحقــق مــن ذلــك،\n مــن بينهــا:\n • مراجعة المستندات اإلدارية للتأكد من أن لكل شركة إدارة مستقلة وحسابات مالية\n منفصلة؛\n • التحقق من اختالف إعداد ومصدر العروض الفنية والمالية؛\n • االنتباه إلى مؤشرات التواطؤ أو التنسيق المسبق ،مثل تشابه األخطاء ،تطابق الحسابات،\n الخط أو التواقيع ،تسلسل الطوابع المالية ،صدور ضمانات العروض عن المصرف نفسه\n بأرقام متسلسلة ،أو أي قرائن أخرى قد تدل على غياب االستقاللية.\n\f37\n .XIIالقسم الثاني عشر :تحالف الشركات\nتقدمــت عــدة شــركات بعــرض واحــد ضمــن تحالــف لتنفيــذ عمليــة شــراء عــام، السـؤال .57فــي حــال ّ\n علــى مــن يتــم إرســاء التلزيــم قانونـ ًـا ؟\nمجتمعاً ،\n ِ الـــــــــجـــــــواب .وفقــاً ألحــكام المــادة 23مــن قانــون الشــراء العــام ،يتــم إرســاء التلزيــم على تحالف الشــركات\nوليــس علــى أي شــركة منفــردة ،وذلــك ألن التحالــف هــو الــذي يملــك ،بصــورة جماعيــة ،المؤهــات\n والخبــرات المطلوبــة لتنفيــذ مشــروع الشــراء.\nعينــوا ،ضمــن مســتندات العــرض وبموجــب عقــد منظم وفقــا لألصول، ُيشــترط أن يكــون الشــركاء قــد ّ\nيمثلهــم أمــام الجهــة الشــارية بالتكافــل والتضامــن .يمنــح التلزيــم لتحالــف الشــركات شــريكاً رئيسـ ًـأ ّ\nويبلّ ــغ الشــريك الرئيــس قــرار اإلرســاء المؤقــت تمهيـ ًـدا لتوقيــع عــن التحالــف العقــد\n كوحــدة واحــدةُ ،\n بعــد اســتكمال اإلجــراءات القانونيــة.\nـدد الجهــة التــي تُ صــرف لصالحهــا المســتحقات الماليــة فــي العقــود المبرمــة\n السـؤال .58كيــف تُ حـ َّ"}, {"o": 49, "l": "المادة ١٠٠", "b": "مــع تحالــف شــركات؟\nمجتمعــاً وفقــاً ألحــكام المــادة 23مــن قانــون الشــراء العــام،\n ِ الـــــــــجـــــــواب .بمــا أن العقــد ُيبــرم مــع تحالــف الشــركات\n فــإن المســتحقات الماليــة تُ صــرف باســم التحالــف ووفقــاً لمــا هــو منصــوص عليــه فــي العقــد.\nيتصــرف\n ّ المفــوض الــذي\n َّ ــا بالشــريك الرئيــس َّ\n ممث ً نظــم حــواالت الصــرف باســم التحالــف عمليــاً ،تُ َّ\nباســم ولحســاب جميــع الشــركاء .وتبقــى كيفيــة توزيــع هــذه المســتحقات بيــن الشــركاء خاضعــة\nالتفــاق التحالــف المنظــم لعالقاتهــم الداخليــة ،دون أن يؤثــر ذلــك علــى مســؤوليتهم التضامنيــة\n تجــاه الجهــة الشــارية.\nالسـؤال .59هــل يجــوز لشــركة أو عضــو فــي تحالــف شــركات أن يشــارك فــي أكثــر مــن عــرض واحــد\n للتلزيم؟\nالـــــــــجـــــــواب .ال يجــوز لشــركة أو عضــو فــي تحالــف الشــركات المشــاركة إال فــي عــرض واحــد للتلزيــم ،ســواء كان\nذلــك بشــكل فــردي أو كشــريك فــي تحالــف .ويــؤدي تقديــم أو مشــاركة نفــس العــارض فــي أكثــر مــن\n عــرض إلــى اعتبــار جميــع العــروض المقدمــة منــه غيــر مقبولــة.\n ً\n واحدا ؟ ً\n عرضا السـؤال .60باسم من يكون ضمان العرض في حالة تحالف شركات ّ\n يقدم\nالـــــــــجـــــــواب .يكــون ضمــان العــرض باســم تحالــف الشــركات الــذي يقـ ّـدم العــرض .ويمكــن أن ُيصــدر ضمــان العــرض\nيوضــح الضمــان أســماء جميــع شــركاء التحالــف،باســم الشــريك الرئيســي فــي التحالــف ،بشــرط أن ّ\n وينــص صراحــة علــى أن الضمــان ُيقـ ّـدم لصالــح وبالنيابــة عــن تحالــف الشــركات بأكملــه.\n السـؤال .61هل يجوز لتحالف شركات تغيير تكوينه أو وضعه القانوني بعد تقديم العرض؟"}, {"o": 50, "l": "المادة ١٠٠", "b": "الـــــــــجـــــــواب .ال يجــوز لتحالــف الشــركات تغييــر تكوينــه أو وضعــه القانونــي بعــد تقديــم العــرض ،ويجــب أن يظــل\n التحالــف كمــا هــو محــدد فــي مســتندات العــرض األصليــة طــوال فتــرة التقييــم والتلزيــم.\n\f 38\n .XIIIالقسم الثالث عشر :تنفيذ عقود الشراء\nالسـؤال .62هــل يمكــن لشــركة ملتزمــة التنــازل عــن جــزء مــن التزامهــا لصالــح شــركة أخــرى لتحــل\nمحلهــا فــي حقوقهــا وواجباتهــا ،مــع احتفاظهــا بجــزء مــن التزامهــا األصلــي ،وذلــك\n فــي ظــل أحــكام قانــون الشــراء العــام؟\nالـــــــــجـــــــواب .اســتناداً إلــى المــادة 30مــن قانــون الشــراء العــام ،يتوجــب علــى الملتــزم األساســي أن يتولــى بنفســه\nويحظــر\n ـؤوال تجــاه ســلطة التعاقــد عــن تنفيــذ جميــع بنــوده وشــروطهُ ،\n تنفيــذ العقــد ،وأن يبقــى مسـ ً\n عليــه التنــازل عــن كامــل موجباتــه التعاقديــة للغيــر.\nنصــت غيــر أنــه ،فــي عقــود األشــغال والخدمــات ،وبصــورة اســتثنائية ،يجــوز للملتــزم األساســي ،وإذا ّ\nشــروط العقــد علــى ذلــك ،أن يعهــد إلــى متعهــد ثانــوي بتنفيــذ جــزء مــن التزاماتــه ،علــى أال تتجــاوز\nـازال\n قيمــة هــذا الجــزء خمســين بالمئــة ( )%50مــن قيمــة العقــد .وفــي هــذه الحالــة ،ال ُيعــد ذلــك تنـ ً\nـؤوال بالكامــل أمــام اإلدارة عــن\n عــن العقــد ،بــل تلزيمــاً جزئيــاً ،علــى أن يبقــى الملتــزم األساســي مسـ ً\n تنفيــذ العقــد ،وأن يســتمر بتنفيــذ جــزء منــه بصــورة شــخصية.\nعلــى الـــملتزم َأخــذ الـــموافقة الــ ُـمسبقة علــى التعاقــد الثانــوي مــن ســلطة التعاقــد التــي يجــب عليهــا\nوي َعـ ّـد\n اتّ خــاذ قرارهــا بالـــموافقة أو الرفــض الـــمعلَّ ل خــال مهلــة زمنيــة تُ حـ َّـدد فــي شــروط العقــدُ ،"}, {"o": 51, "l": "المادة ١٠٠", "b": "ســكوتها عنــد انقضــاء هــذه الـــمهلة قــراراً ضمنيــاً بالقبــول.\n\f39\n .XIVالقسم الرابع عشر :مشاركة العارضين االجانب\n السـؤال .63كيف يمكن للعارض األجنبي المشاركة في إجراءات الشراء العام في لبنان؟\nالـــــــــجـــــــواب .علــى العــارض األجنبــي الــذي يرغــب بالمشــاركة فــي إجــراءات الشــراء العــام أن يراعــي أحــد الشــروط\n التاليــة:\n .1أن يكون ضمن ائتالف يضم شركة لبنانية واحدة على األقل تتوفر فيها الشروط المطلوبة\n بموجب دفتر الشروط الخاص بالصفقة.\n .2الحضور الشخصي للممثل القانوني عن الشركة للمشاركة في إجراءات الشراء.\n .3أن يكون له وكيل أو ممثل في لبنان مكلف بحضور جلسات التلزيم وبتوقيع العقد نيابة\n عنه.\n باإلضافة إلى ما تقدم ،يتوجب على العارض األجنبي تقديم المستندات التالية:\n .1شهادة تسجيل الشركة أو المؤسسة لدى المراجع المختصة في بلده.\n .2إفادة من وزارة االقتصاد والتجارة اللبنانية تثبت انطباق أحكام قانون مقاطعة اسرائيل\n لعام .1955\nكل ذلــك وفقــا ألحــكام دفتــر الشــروط الخــاص بالمناقصــة ومذكــرة هيئــة الشــراء العــام رقــم 2023/8\nتاريــخ 2023/12/12والمذكــرة رقــم 2024/9تاريــخ 2024/10/23حــول اإلفــادات والمســتندات التــي\n يجــب أن تتضمنهــا دفاتــر الشــروط الخاصــة مــن ضمــن الشــروط اإلداريــة.\n ّ\nممثلــون فــي لبنــان ،فهــل مــوردون أو\n ّ السـؤال .64إذا كانــت الشــركة األم فــي الخــارج لديهــا\n ّ\nممثليهــا المحلييــن؟ وهــل تتعاقــد الجهــة الشــارية مباشــرة مــع الشــركة األم أم مــع\nُيشــترط المــرور عبــر شــركة وطنيــة للتعاقــد مــع الشــركة األم ،حتــى ولــو كانــت هــذه\n جيــدة بســعر مناســب؟\n ـدم خدمــة ّ دا شـ ً\n ـامال وتقـ ّ ـور ً\n األخيــرة مـ ّ"}, {"o": 52, "l": "المادة ١٠٠", "b": "الـــــــــجـــــــواب .ليــس هنالــك مــن إلــزام قانونــي بالتعاقــد مباشــرة مــع الشــركة األم مــا لــم يكــن هناك مبــرر موضوعي\n(المــادة 46مــن قانــون الشــراء العــام) .وبموجــب القانــون ،ال توجــد أولويــة للشــركات الوطنيــة\n(األولويــة فــي القانــون هــي للمنتجــات والخدمــات الوطنيــة وليــس للشــركات) .وفقــاً للقانــون يجــب\n أن تتمتــع الشــركات الدوليــة والوطنيــة بفــرص متســاوية.\n\f 40\n .XVالقسم الخامس عشر :السرية ،الشفافية والنشر\n السـؤال .65ما هي أنواع المناقصات التي تخضع ألحكام السرية؟\nالـــــــــجـــــــواب .حــددت المــادة - 46فقــرة -4مــن قانــون الشــراء العــام شــروط التعاقــد بالتراضــي للشــراء الــذي\nيســتلزم المحافظــة علــى طابعــه الســري مــن أجــل مقتضيــات األمــن أو الدفــاع الوطنــي ،وذلــك\nـاء علــى اقتــراح الوزيــر المختــص الــذي يحــدد الصفــة الســرية\n وفقــاً لقــرار يتخــذ فــي مجلــس الــوزراء بنـ ً\n للشــراء وأســباب التعاقــد الرضائــي.\nتطبــق المذكــرة رقــم ٢تاريــخ 2026/1/21الصــادرة عــن هيئــة الشــراء العــام والتــي تطلــب فيهــا مــن\n الجهــات الخاضعــة ألحــكام قانــون الشــراء العــام:\n .1اعتبار أي قرار صادر باالستناد إلى الفقرة ٤من الماَّدَ ة ٤٦من قانون الشراء العام منقضي\n المفعول بعد اجراء االتفاق الرضائي للوازم واألشغال والخدمات ذات الطابع السري\n المسند إليه.\n .2وجوب تقديم طلب منفصل لمجلس الوزراء عبر الوزير المختص في كل مَّرَ ة أرادت الجهة\n سنًدا للمادة 46فقرة 4من قانون الشراء العام تبِّيِ ن فيه:\n ً الشارية إجراء عقد اتفاق رضائي\n • كيفَّيَ ة انطباق توصيف «األمن» أو «الدفاع الوطني» على موضوع االتفاق الرضائي\n المطلوب.\n • األسباب الموجبة إلعطاء اللوازم واألشغال او الخدمات موضوع التعاقد الطابع السري."}, {"o": 53, "l": "المادة ١٠٠", "b": "السـؤال .66هــل يمكــن للجهــة الشــارية االمتنــاع عــن نشــر المواصفــات الفنيــة المطلوبــة إذا كان\n ذلــك ضروريـ ًـا لحمايــة أمــن األنظمــة المعلوماتيــة؟\nالـــــــــجـــــــوابُ .يحـ َّـدد ذلــك علــى أســاس كل حالــة علــى حــدة باالســتناد إلــى األحــكام ذات الصلــة الــواردة فــي قانــون\nعرفــت الســرية فــي الشــراء العــام ،وبمــا يــوازن\n الشــراء العــام ،وعمــا بالمــادة 6مــن هــذا القانــون التــي ّ\n بيــن متطلبــات الشــفافية وحمايــة أمــن األنظمــة المعلوماتية.\n ً\nواجبا نشــرها السـؤال .67فــي حــال عــدم نشــر العقــود الســابقة بســبب تأخيــرات إداريــة ،هــل يبقــى\n بعــد انقضــاء المهلــة المحددة؟\nالـــــــــجـــــــواب .نعــم ،يبقــى النشــر واجبــاً حتــى بعــد مــرور المهلــة المحــددة ،إذ إن النشــر المتأخــر ُيعـ ّـد أفضــل مــن\nعــدم النشــر إطالقــاً .فالشــفافية تُ شــكّ ل أحــد المبــادئ األساســية لقانــون الشــراء العــام وتُ عتبــر مــن\n النظــام العــام.\nـا ،يتوجــب علــى الجهــة الشــارية نشــر ملخــص\n وفــي حــال وجــود أســباب تحــول دون نشــر العقــد كامـ ً\nعنــه علــى األقــل ،يتضمــن البنــود اإلداريــة والماليــة األساســية وتعليــل أســباب عــدم نشــر كامــل\n العقــد.\n السـؤال .68ما العالقة بين تاريخ نفاذ العقد وتاريخ نشره؟\nالـــــــــجـــــــواب .تعتبــر العقــود نافــذة بمجــرد توقيــع الطرفيــن عليهــا .الهــدف مــن النشــر هــو اطــاع الغيــر وتأميــن\n أكبــر قــدر مــن الشــفافية ،امــا تواريــخ التنفيــذ فتحــدد فــي متــن العقــود ذاتهــا.\n\f41\nالسـؤال .69هــل مــن الممكــن إرســال نســخة إلكترونيــة (قــرص مدمــج أو بريــد إلكترونــي) عــن\n ً"}, {"o": 54, "l": "المادة ١٠٠", "b": "بــدال مــن النســخة الورقيــة؟ التقاريــر الســنوية بعمليــات الشــراء المجــراة\n الـــــــــجـــــــواب .ال تمانــع هيئــة الشــراء العــام مــن إرســال نســخة إلكترونيــة عــن التقاريــر الســنوية لعمليــات الشــراء بـ ً\nـدال\n التقيــد بمــا يلــي:\n ّ مــن النســخة الورقيــة علــى أن يتـ ّـم\n الُمدرجة في مذكرة هيئة الشراء العام رقم 4• تعبئة كافة النماذج ُ\n https://www.ppa.gov.lb/ar/pages/details/44تاريخ .2024/7/24\n • إرسال نسخة إلكترونية عن كل نموذج يتم تعبئته إلى هيئة الشراء العام على البريد\n اإللكتروني المحدد في المذكرة المشار إليها أعاله.\n • إرسال نسخة إلكترونية على قرص مدمج (مرفق بإحالة ورقية موقعة وفقًاً لألصول) عن\n كل نموذج يتم تعبئته وارساله الى هيئة الشراء العام.\nالسـؤال .70هــل تُ عتبــر صفقــات أنظمــة تكنولوجيــا المعلومــات واألمــن الســيبراني صفقــات سـ ّـرية\nبالمعنــى المقصــود فــي الفقــرة الرابعــة مــن المــادة 46مــن قانــون الشــراء العــام،\n وبالتالــي غيــر خاضعــة لإلجــراءات التنافســية ولموجــب النشــر؟\nالـــــــــجـــــــواب .إن صفقــات أنظمــة تكنولوجيــا المعلومــات ،بمــا فيهــا أنظمــة األمــن الســيبراني ،والنظــم المحاســبية\nعد صفقات سـ ّـرية بكاملها بالمعنى األساســية ( ،)Core Systemsوأنظمة الشــبكات والحماية ،ال تُ ّ\nالمقصــود فــي الفقــرة الرابعــة مــن المــادة 46مــن قانــون الشــراء العــام .فالمقصــود بالصفقــات\nالسـ ّـرية هــو الصفقــات التــي تكــون بطبيعتهــا وبكامــل عناصرهــا خاضعــة لمقتضيــات األمــن أو الدفــاع\n الوطنــي ،بحيــث ال يجــوز أن تصــل إلــى علــم الغيــر إطالقــاً.\nأمــا صفقــات تكنولوجيــا المعلومــات ،فهــي غالبــاً مــا تتضمــن عناصــر أو مواصفــات فنيــة ذات طابــع"}, {"o": 55, "l": "المادة ١٠٠", "b": "سـ ّـري تســتوجب الحماية ألســباب تتعلق باألمن الوطني أو األمن المعلوماتي ،دون أن يؤدي ذلك\n إلــى إخضــاع الصفقــة برمتهــا لنظــام السـ ّـرية الكاملــة أو إعفائهــا مــن مبــدأي المنافســة والشــفافية.\nوعليــه ،يجــوز إجــراء هــذا النــوع مــن الصفقــات ضمــن إجــراءات تنافســية ،مــع اعتمــاد تدابيــر مناســبة\nلحمايــة المعلومــات الحساســة ،مثــل اللجــوء إلــى المناقصــة بعــد التأهيــل المســبق ،وحصــر االطــاع\nعلــى المواصفــات التفصيليــة بالعارضيــن المؤهليــن ،وإلزامهــم بتوقيــع اتفاقيــات عــدم اإلفشــاء،\n وذلــك تطبيقــاً لمبــدأ التناســب ووفقــاً ألحــكام قانــون الشــراء العــام.\n\f 42\n .XVIالقسم السادس عشر :تطبيقات عملية في تنفيذ قانون الشراء العام\nالسـؤال .71تواجــه العديــد مــن البلديــات صعوبــات ماليــة تمنعهــا مــن توظيــف موظفيــن جــدد\nإلنشــاء وحــدات شــراء متخصصــة كمــا يفــرض قانــون الشــراء العــام .كيــف يمكنهــا\n االلتــزام بالقانــون فــي هــذه الحالــة؟\n الـــــــــجـــــــواب .ال يفــرض قانــون الشــراء العــام علــى البلديــات توظيــف موظفيــن جــدد إلنشــاء وحــدة الشــراء .بـ ً\nـدال\nمــن ذلــك ،يمكنهــا تكليــف موظفيــن حالييــن أو أعضــاء مــن المجلــس البلــدي بمهــام الشــراء ،شــرط أن\nيخضعــوا للتدريــب الــازم المنصــوص عليــه فــي المــادة 72مــن قانــون شــراء العــام مــع مراعــاة قاعــدة\n تضــارب المصالــح.\nويجــب أن يتناســب حجــم وتركيبــة الوحــدة مــع حجــم وتعقيــدات عمليــات الشــراء ،ويمكــن إنشــاؤها\n ـدال مــن إنشــاء كيــان إداري جديــد.\n مــن خــال تكييــف الهيكليــة اإلداريــة القائمــة بـ ً\n مكملة ،منها:\n ّ كما ُيستحسن أن تتخذ البلديات خطوات\n •انشاء وحدة التدقيق الداخلي،\n •تشكيل لجان التلزيم ولجان االستالم،"}, {"o": 56, "l": "المادة ١٠٠", "b": "•إعداد خطة الشراء السنوية،\n •التنسيق مع هيئة الشراء العام للحصول على الدعم الفني والتدريب.\nالسـؤال .72هــل يحــق للجهــة الشــارية تمديــد مهلــة تنفيــذ صفقــة تقديــم يــد عاملــة وفقـ ًـا لقانــون\n الشــراء العــام ،فــي ظــل ظــروف اســتثنائية؟\nالـــــــــجـــــــواب .يحــق للجهــة الشــارية تمديــد مهلــة تنفيــذ صفقــة تقديــم يــد عاملــة فــي حــال توافــر ظروف اســتثنائية،\nوذلــك اســتناداً إلــى نظريــة الظــروف االســتثنائية متــى توافــرت شــروطها .إذ تنــص المــادة 102مــن\nقانــون الشــراء العــام علــى أن الجهــة الشــارية تتحمــل المســؤولية فــي إدارة العقــد ،وتقديــر الظــروف\n المحيطــة بتنفيــذه ،واتخــاذ القــرارات الالزمــة لضمــان حســن التنفيــذ واســتمرارية المرفــق العــام.\nوفــي حــال نشــوء ظــروف اســتثنائية ،يجــوز للجهــة الشــارية اتخــاذ التدابيــر التــي تراهــا مناســبة لضمــان\nســير المرفــق العــام ،بمــا فــي ذلــك تمديــد مهلــة التنفيــذ ،علــى أن يقتصــر هــذا التمديــد علــى حــدود\nالحاجــة الفعليــة الســتمرارية المرفــق العــام .كمــا يجــب أن يتــم التمديــد بمــا يتوافــق مــع الشــروط\nالتعاقديــة النافــذة ،ووفــق اآلليــات التــي تعتمدهــا الجهــة الشــارية ،وذلــك فقــط فــي الحــاالت التــي\n يصعــب فيهــا تأميــن الحاجــة بالطــرق العاديــة.\n السـؤال .73هل من الممكن تمديد إيجار مبنى عائد للبلدية إلى ما بعد انتهاء فترة العقد؟\n الـــــــــجـــــــواب .تمتلك البلديات نوعين من األمالك:\n .1الملك البلدي العام :يشمل الساحات والطرقات ،وهذا النوع ال يقبل البيع وال التأجير وال\n الحجز عليه.\n .2الملك البلدي الخاص :يشمل العقارات والمباني التي تملكها البلديات كاألفراد ،ويجوز لها"}, {"o": 57, "l": "المادة ١٠٠", "b": "بيعها أو تأجيرها وفقًاً ألحكام القوانين واألنظمة النافذة ،وتخضع عمليات استثمارها\n لقواعد وأصول مماثلة لتلك التي ُتُ طَّبَ ق على أمالك الدولة.\n\f43\nتنــص المــادة 60مــن القــرار رقــم 275تاريــخ ( 1926/5/25إدارة وبيــع أمــاك الدولــة الخاصــة) علــى أن\nالعقــارات الداخلــة ضمــن أمــاك الدولــة فــي المــدن تُ ؤجــر بعــد اإلعــان عنهــا لمــدة ال تزيــد عــن أربــع\nســنوات ،علــى أن ُيحــدد ســعر افتتــاح المزايــدة بموجــب كشــف إداري .وفــي األحــوال التــي ال تُ ؤجــر\nفيهــا العقــارات إلدارة عموميــة ،أو لمصلحــة المنفعــة العامــة ،أو إلحــدى البلديــات ،يجــب أن يتــم\n التأجيــر بالمــزاد العلنــي.\nـاء عليــه ،يجــب علــى البلديــة إنهــاء عقــد اإليجــار عنــد انتهــاء مدتــه إذا كان المســتأجر جهــة خاصــة،\n وبنـ ً\n ومــن ثــم تنظيــم مزايــدة عموميــة لتأجيــر العقــار مــرة أخــرى وفقــاً ألحــكام قانــون الشــراء العــام.\nالسـؤال .74قــد تــؤدي كثــرة المســتندات المطلوبــة إلثبــات اســتيفاء شــروط المشــاركة ،وصعوبــة\nـدم .ما الحل لتســهيل المشــاركة\n الحصــول علــى بعضهــا ،إلــى إحجــام العارضيــن عن التقـ ّ\n دون اإلخــال بمبادئ الشــفافية والمنافســة؟\nالـــــــــجـــــــواب .يتمثــل الحــل فــي النــص ضمــن دفتــر الشــروط علــى إمكانيــة إعــادة المســتندات األصليــة إلــى العــارض\nبعــد تقديمهــا ،مــع احتفــاظ الجهــة الشــارية بنســخ عنهــا ،علــى أن تكــون هــذه المســتندات قابلــة\n لإلعــادة وأال تُ عــد مــن المســتندات األساســية ،مثــل العــرض الفنــي.\nومــن شــأن هــذا اإلجــراء أن يسـ ّـهل المشــاركة علــى العارضيــن ،إذ يتيــح لهــم اســتخدام المســتندات\n نفســها فــي إجــراءات شــراء أخــرى ،شــرط أن تكــون صالحــة وســارية المفعــول."}, {"o": 58, "l": "المادة ١٠٠", "b": "السـؤال .75كيــف يمكــن التعامــل مــع المناقصــات التــي تســفر عــن عــدم تلقــي عــروض أو تلقــي\nعــرض وحيــد غيــر مقبــول ،خاصــة عندمــا تكــون المناقصــات مرتبطــة بأعمــال صيانــة\n فوريــة تتطلــب تعاقـ ً\n ـدا عاجـ ً\n ـا؟\nالـــــــــجـــــــواب .فــي هــذه الحالــة ،قــد تكــون مراجعــة ملفــات التلزيــم أمــراً ضروريــاً للتحقــق ممــا إذا كانــت تتضمــن\nشــروطاً أو مواصفــات أو أحكامــاً تــؤدي إلــى تــردد المشــاركين المحتمليــن فــي التقــدم بعروضهــم،\n وفــي حــال وجــود ذلــك ينبغــي تعديــل هــذه األحــكام.\nكمــا يجــب مراجعــة المســتندات المطلوبــة والتأكــد مــن مالءمتهــا ،ســواء مــن حيــث كثرتهــا أو صعوبة\n الحصــول عليها.\n إضافـ ًـة إلــى ذلــك ،يمكــن أن ُيعــد اســتخدام االتفــاق اإلطــاري أداة ّ\nفعالــة للتعامــل مــع احتياجــات\n الشــراء العاجلــة أو المتكــررة أو غيــر المتوقعــة.\nطبــق التوقيفــات العشــرية فــي عقــود اللــوازم وفقـ ًـا لقانــون الشــراء العــام ،ومــا\n السـؤال .76هــل تُ َّ\n هــي الضوابــط التــي تحكــم اقتطاعها؟\nالـــــــــجـــــــواب .تطبــق التوقيفــات العشــرية فــي عقــود اللــوازم ،وال يقتصــر تطبيقهــا علــى عقــود األشــغال أو\nنظمــت آليــة دفــع قيمــة العقــد دون ربــط\n الخدمــات ،إذ إن المــادة 37مــن قانــون الشــراء العــام ّ\n اقتطــاع التوقيفــات العشــرية بطبيعــة الصفقــة.\n\f 44\n وبموجب المادة ،37تسري القواعد التالية:\n • قاعدة التنفيذ ثم الدفع ،بحيث تُ دفع قيمة العقد بعد تنفيذ موجبات المتعاقد؛\n • عند تنفيذ العقد على مراحل ،يتم الدفع بالتناسب مع المنجزات ،على أاّلا تتجاوز الدفعات\n قبل االستالم النهائي تسعة أعشار ( )10/9المبلغ المستحق ،ويبقى العشر موقوفًاً في\n الخزينة إلى حين االستالم النهائي؛"}, {"o": 59, "l": "المادة ١٠٠", "b": "• تتمتع سلطة التعاقد بصالحية تقديرية في اقتطاع توقيفات عشرية من الدفعات ،ضمن\n تبّقى من تنفيذ العقد؛سقف التسعة أعشار ،وبالقدر الذي تراه كافيًاً لتغطية مخاطر ما ّ\n • يجوز استبدال التوقيفات العشرية بضمانات موازية متى كانت هذه الضمانات كافية\n لتغطية المخاطر القائمة؛\n • لم يربط القانون تطبيق التوقيفات العشرية بطبيعة الصفقة ،وبالتالي فهي ُتُ طَّبَ ق على\n صفقات اللوازم واألشغال والخدمات على السواء.\nميــزت المــادة 37بيــن التوقيفــات العشــرية والســلفات ،حيــث أجــازت إعطــاء ســلفات بنســبة ال كمــا ّ\nتتجــاوز %20مــن قيمــة العقــد ،علــى ّأاّل تتجــاوز فــي أي حــال مــن األحــوال ســقفاً ماليــاً محــددا قــدره\n 15مليــار ليــرة لبنانيــة ،وذلــك مقابــل كفــاالت مصرفيــة.\nوفــي عقــود اللــوازم ذات التســليم الواحــد ،وبالنظــر إلــى محدوديــة مخاطــر التنفيــذ ،يمكــن لســلطة\n التعاقــد:\n • تحديد قيمة ضمان حسن التنفيذ مع األخذ باالعتبار أن عشر المبلغ المستحق يبقى موقوفًاً\n علًما أن ضمان حسن التنفيذ محدد قانونًاً بسقف أقصى ال\n إلى حين االستالم النهائيً ،\n يتجاوز %10من قيمة العقد دون فرض حد أدنى؛\n ربًطا بضمانات التشغيل أو\n • تقريب االستالم النهائي من االستالم المؤقت قدر اإلمكانً ،\n فترات التجربة واالختبار.\nالسـؤال .77هــل يجــوز للجهــة الشــارية الســماح ألحــد العارضيــن ،بنــاء لطلبــه ،باالطــاع علــى الحــل\nالتقنــي المعتمــد مــن قبــل العارضيــن المؤهليــن فنيـ ًـا بمــا فيهــم العــارض الفائــز فــي\n المناقصــة؟\nالـــــــــجـــــــواب .اســتنادا إلــى مــا نــص عليــه قانــون الشــراء العــام ،وتحديــدا المــادة ،6البند 4من المــادة ،9والبند 1من\nالمقدمــة ضمــن العــروض تعتبــر مــن المعلومــات ّ المــادة 110منــه ،فــإن المســتندات الفنيــة والتقنيــة"}, {"o": 60, "l": "المادة ١٠٠", "b": "الهامــة وبعضهــا قــد تتضمــن بيانــات محميــة تتعلــق باألســرار التجاريــة واالمتيــازات التقنيــة للعارضيــن\n التــي تتمتّ ــع بالطابــع الســري خــال كافــة مراحــل التلزيم.\nبالتالــي ،ال يمكــن الكشــف عــن الحلــول التقنيــة الخاصــة بالعارضيــن المرشــحين أو الفائزيــن ألي جهــة،\nحفاظــاً علــى مبــدأ المنافســة ومنــع اإلضــرار بالمصالــح التجاريــة المشــروعة للعارضيــن ،ولضمــان\n حياديــة ومصداقيــة إجــراءات الشــراء العــام.\nالسـؤال .78كيــف تُ حتســب الحســومات فــي حــال وجــود نواقــص أو عيــوب طفيفــة وغيــر جوهريــة\n عنــد االســتالم ،وال ســيما عندمــا يتعـ ّ\n ـذر إتمامهــا أو إصالحهــا؟\n الـــــــــجـــــــوابّ .\nإن هــذه المســائل ،بمــا فيهــا الغرامــات وآليــات حـ ّـل النزاعــات وغيرهــا مــن اإلشــكاالت التــي قــد تنشــأ\nأثنــاء تنفيــذ العقــد ،يجــب أن تُ حـ َّـدد بالتفصيــل فــي الشــروط العامــة والشــروط الخاصــة للعقــد ،بمــا\n فــي ذلــك كيفيــة معالجتهــا والتعامــل معهــا.\n\f45\n .XVIIمراجع مفيدة\n .1موقع الهيئة االلكتروني www.ppa.gov.lb\n .2قانون الشراء العام رقم .2021/244\n .3مذكرات هيئة الشراء العام.\n .4قرارات هيئة الشراء العام.\n .5توصيات هيئة الشراء العام.\n .6دفاتر الشروط النموذجية.\n .7دليل عمل اللجان.\n .8نماذج صادرة عن الهيئة.\n\fُُأنجــز هــذا الكتيــب بدعــم مــن االتحــاد األوروبــي ،فــي إطــار مشــروع دعــم إصالح اإلدارة العامــة فــي\nالمنّفــذ مــن قبــل إكســبيرتيز فرانــس ،ويقــع مضمونــه تحــت المســؤولية الحصريــة لـــ «هيئــة\n ّ لبنــان،\n الشــراء العــام » وال يعكــس بالضــرورة وجهــات نظــر االتحــاد األوروبــي."}]$j$::jsonb) e;
